// HVORFOR – LettFagprøve
// Kort forklaring på hvorfor hvert galt svaralternativ er galt. Nøkkel: spørsmåls-id, så teksten til det gale alternativet.
window.HVORFOR = {
  "g1": {"0,2 A":"0,2 A er 46 delt på 230, altså tallene snudd. Ohms lov er spenning delt på resistans, I = U / R.","50 A":"50 A er for stort, og da har du flyttet komma eller delt feil. Ohms lov gir I = U / R = 230 / 46.","10 580 A":"10 580 A er 230 ganger 46, altså spenning ganger resistans. Strøm får du ved å dele spenningen på resistansen."},
  "g2": {"0,1 A":"0,1 A er for lite. Da har du delt spenningen på effekten, U / P, i stedet for P / U.","23 A":"23 A er for stort, for det ser ut som du har delt 2300 på 100. Riktig formel er I = P / U, med 230 V.","529 A":"529 A er 2300 ganger 230, altså effekt ganger spenning. Strøm får du ved å dele effekten på spenningen."},
  "g3": {"5,45 Ω":"5,45 Ω er regnet som parallell, med 1/R = 1/R1 + 1/R2 + 1/R3. I serie skal motstandene legges sammen, ikke deles.","20 Ω":"20 Ω er bare én av motstandene, og de andre to er glemt. I serie skal alle tre legges sammen: 10 + 20 + 30.","6 000 Ω":"6 000 Ω er altfor høyt. De tre motstandene er bare noen titalls ohm, og summen blir ikke tusenvis."},
  "g4": {"20 Ω":"20 Ω er det du får ved å legge sammen i serie. I parallell blir totalen mindre enn den minste motstanden.","10 Ω":"10 Ω er bare én av motstandene, og den andre er glemt. I parallell blir totalen mindre enn én motstand alene.","100 Ω":"100 Ω er 10 ganger 10, altså produktet. I parallell deler du, og da blir totalen mindre, ikke større."},
  "g5": {"Den dobles":"Hvis tverrsnittet dobles, blir ledningen bedre og ikke dårligere. Tverrsnittet står i nevneren i R = ρ · L / A, så R blir mindre.","Den blir uendret":"Tverrsnittet står i formelen for resistans, R = ρ · L / A. Når A endres, endres R, så den blir ikke uendret.","Den firedobles":"Firedobling skjer bare hvis tverrsnittet blir fire ganger mindre. Når tverrsnittet dobles, blir R mindre, ikke fire ganger så stor."},
  "g6": {"7 Ω":"7 Ω er ti ganger for mye. Da har du delt på 0,25 i stedet for 2,5.","0,07 Ω":"0,07 Ω er ti ganger for lite. Da har du brukt 10 meter i stedet for 100, eller flyttet et desimaltegn feil.","1,4 Ω":"1,4 Ω er for fram- og returlederen sammen, altså to ledere. Spørsmålet spør om én leder, så den skal ikke dobles."},
  "g7": {"0,67 kWh":"0,67 kWh er 2 delt på 3, altså effekt delt på tid. Energi er effekt ganger tid, ikke delt.","1,5 kWh":"1,5 kWh er 3 delt på 2, altså tid delt på effekt. Energi er effekt ganger tid: 2 kW · 3 h.","5 kWh":"5 kWh er 2 pluss 3, altså effekt og tid lagt sammen. Energi får du ved å gange effekt med tid."},
  "g8": {"Summen av spenningene rundt en lukket krets er lik null":"Dette handler om spenning rundt en lukket krets. Kirchhoffs strømlov handler om strøm inn og ut av et knutepunkt.","Strømmen er lik i alle grener av en parallellkobling":"Strømmen deler seg i en parallellkobling, så den er ikke lik i alle grener. Strømlova handler om knutepunkt, ikke om grener.","Summen av strømmer inn i et knutepunkt er lik spenningen delt på resistansen":"Her er Ohms lov blandet inn. Spenning delt på resistans gir strømmen i én leder, ikke summen av strømmer i et knutepunkt."},
  "v1": {"60 Hz":"60 Hz er ikke frekvensen i det norske nettet. Det norske og europeiske nettet har en lavere frekvens.","16,7 Hz":"16,7 Hz er mye lavere enn nettfrekvensen i Norge. Den er ikke riktig for det norske nettet.","100 Hz":"100 Hz er for høyt. Nettet i Norge går på en lavere frekvens enn dette."},
  "v2": {"230 V":"230 V er effektivverdien, den vi måler med vanlig multimeter. Toppverdien er høyere, og den får du når du ganger med √2.","163 V":"163 V er 230 delt på √2, altså motsatt vei. Toppverdien får du ved å gange med √2, ikke ved å dele.","400 V":"400 V er altfor høyt for toppverdien av 230 V. Den regnes ut med √2, og resultatet blir litt over 300."},
  "v3": {"Ca. 400 V":"400 V er spenningen mellom to faser i et TN-nett. Fase–nøytral er lavere, fordi den er delt på √3.","Ca. 690 V":"690 V er 400 ganger √3, altså feil regning. Fase–nøytral skal være 400 delt på √3, og da blir den lavere, ikke høyere.","Ca. 115 V":"115 V er feil. Fasespenningen er linjespenningen delt på √3, altså 400 delt på 1,73."},
  "v4": {"Ca. 2,3 kW":"2,3 kW er bare én fase: 230 V ganger 10 A. Trefase skal ganges med √3 og med 400 V.","Ca. 4,0 kW":"4,0 kW er 400 V ganger 10 A. Da har du glemt √3 i formelen for trefase.","Ca. 12 kW":"12 kW er tre ganger 4 kW. Du skal bruke √3, som er omtrent 1,73, og ikke 3."},
  "v5": {"Forholdet mellom reaktiv effekt (Q) og tilsynelatende effekt (S)":"Dette er reaktiv effekt delt på tilsynelatende effekt, og det er en annen størrelse. Cos φ bruker aktiv effekt P delt på S.","Forholdet mellom strøm og spenning, altså motstanden i kretsen":"Cos φ er ikke et forhold mellom strøm og spenning. Den regnes ut av effektene, som cos φ = P / S.","Hvor mange faser anlegget har, og om lasten er trefase":"Antall faser sier ikke noe om cos φ. Cos φ regnes ut av aktiv og tilsynelatende effekt, altså P / S."},
  "v6": {"W":"W er enheten for aktiv effekt, altså den nyttige effekten. Tilsynelatende effekt har en egen enhet.","var":"var er enheten for reaktiv effekt, altså effekten som pendler fram og tilbake. Den er ikke enheten for S.","kWh":"kWh måler energi over tid, ikke effekt. Det er en enhet for hvor mye du bruker, ikke for effektens størrelse."},
  "v7": {"Strømmen ligger foran spenningen":"Det er omvendt. Foran gjelder for kapasitiv last, ikke for en motor, som er induktiv.","Strømmen er null":"Det stemmer ikke. En motor som går, trekker strøm. Strømmen er forskjøvet i forhold til spenningen, men den er ikke null.","De er i fase med hverandre":"I fase betyr at strøm og spenning topper samtidig. Det skjer bare ved rent resistiv last, og en motor er induktiv."},
  "v8": {"400 V":"400 V er spenningen i et TN-nett med nøytral. Mellom to faser i dette IT-nettet er spenningen lavere.","133 V":"133 V er spenningen mellom fase og nøytral i et TN-nett. I et IT-nett finnes ingen nøytralleder, så den spenningen finnes ikke her.","0 V":"0 V betyr at det ikke er spenning. Mellom to faser i dette nettet er det full spenning, så 0 V er feil."},
  "r1": {"300 mA":"300 mA brukes blant annet som brannvern, men gir ikke tilleggsbeskyttelse for personer. Til det kreves en mye lavere utløsestrøm.","3 A":"3 A er for høy strøm for personvern. En jordfeilbryter for personvern må løse ut ved mye lavere strøm enn dette.","1 A":"1 A er også for høyt for personvern. Utløsestrømmen for personbeskyttelse er mye lavere enn dette."},
  "r2": {"5–10 × In":"5–10 × In er C-karakteristikk, ikke B. B-vernet løser ut momentant ved lavere verdi enn dette.","10–20 × In":"10–20 × In er D-karakteristikk. Med B-vern ville utløsningen komme for sent ved kortslutning.","1,13 × In":"1,13 × In er ikke grensen for momentan utløsning. Det er strømmen vernet tåler lenge uten å løse ut, altså en overlastgrense."},
  "r3": {"Beskytte personer mot elektrisk støt ved jordfeil på 30 mA":"Dette er jordfeilbryterens oppgave, ikke sikringens. Overstrømsvern beskytter ledere mot for høy temperatur, ikke personer mot støt.","Begrense spenningen ved lynnedslag og koblinger":"Dette er overspenningsvernets jobb. Sikringen bryr seg om strømmen i lederne, ikke om korte spenningstopper fra lyn.","Skille kursen fra spenning når du skal jobbe på den":"Å skille kursen fra spenning gjøres med frakobling og kontroll. En sikring er ikke beregnet til dette."},
  "r4": {"Type AC":"Type AC registrerer bare vanlig vekselstrøm. Den ser ikke glatt DC, så den passer ikke til elbillading.","Type A":"Type A ser pulserende DC, men ikke glatt DC. Alene er den ikke nok ved elbillading, uten ekstra DC-deteksjon.","Alle typer gjør dette":"Det er ikke riktig. Ikke alle typer ser glatt DC. Bare én spesiell type gjør det, og den må velges for elbillading."},
  "r5": {"Spenningen mellom fase og jord på den beskyttede kursen, målt i volt":"En jordfeilbryter måler ikke spenning. Den reagerer på om strømmen inn og ut er ulik.","Temperaturen i kabelen og overbelastningsstrømmen i de aktive lederne ved drift":"Den måler ikke temperatur. Overbelastning er det overstrømsvernet tar seg av, ikke jordfeilbryteren.","Den totale effekten på kursen, målt i watt ved fullt uttak fra lasten":"Effekt i watt måles ikke av jordfeilbryteren. Den sammenligner bare strømmen i fram- og returlederen."},
  "r6": {"At alle vern løser ut samtidig":"Da slår alle av, og hele anlegget blir uten strøm. Det er motsatt av selektivitet, som bare kobler ut den delen med feil.","At vernet løser ut så sakte som mulig":"Sakte utløsning er farlig, fordi feilen kan vare lenge. Selektivitet handler om hvilket vern som slår ut, ikke hvor sakte det er.","At vernet er av samme type som hovedsikringen":"Vern av samme type er ikke kravet for selektivitet. Det avgjørende er at vernet nærmest feilen kobler ut."},
  "r7": {"Hindre overbelastning av kurser ved å kutte strømmen ved stor last":"Dette er overstrømsvernets jobb. Overspenningsvern reagerer på korte spenningstopper, ikke på stor last.","Gi personbeskyttelse mot jordfeil ved å koble ut strømmen ved berøring":"Dette er jordfeilbryterens jobb. Overspenningsvern kobler ikke ut ved berøring og gir ikke personvern mot støt.","Redusere strømforbruket ved å koble fra utstyr som står på standby":"Overspenningsvern sparer ikke strøm. Det leder bort korte spenningstopper for å beskytte utstyret og installasjonen."},
  "bf1": {"Automatsikring på 30 A, som løser ut ved overlast og kortslutning":"Dette er ikke en automatsikring på 30 A. Merkingen IΔn 0,03 A viser jordfeilstrøm, ikke overstrøm.","Overspenningsvern (type 2) som begrenser spenningen ved lynnedslag":"Et overspenningsvern har ikke merkingen IΔn. Denne komponenten måler lekkasjestrøm til jord, og er en jordfeilbryter.","Kontaktor for styring av motor, med hjelpekontakter og overlastvern":"En kontaktor brukes til å koble motorer. Merket IΔn viser at dette er en jordfeilbryter, ikke en kontaktor."},
  "bf2": {"Jordfeil der strøm går gjennom en person som står på jord":"Den beskytter mot dette. Når strøm går gjennom en person til jord, er strømmen inn og ut ikke lik, og den løser ut.","Lekkasjestrøm til jord fra et defekt apparat":"Dette er noe den beskytter mot. Lekkasje til jord gir ulik strøm inn og ut, og da løser den ut.","Jordfeil i en varmekabel i gulvet på badet":"Dette er en jordfeil, og den reagerer på den. Når strøm lekker til jord, er strømmen inn og ut ikke lik."},
  "e1": {"Automatsikring 16 A uten jordfeilvern, B-karakteristikk, bryteevne 3 kA":"Dette er ikke en vanlig automat uten jordfeilvern. Merkingen viser C-karakteristikk, og vernet har også jordfeilvern.","Jordfeilbryter 160 mA type AC, uten overstrømsvern og med 25 A":"Tallene passer ikke. Vernet har 16 A og type A, og det har både overstrøms- og jordfeilvern.","Overspenningsvern for 230 V, type 2, med 4 kV bærekapasitet":"Dette er ikke et overspenningsvern. Bokstavene og tallene viser et jordfeil- og overstrømsvern, ikke et vern mot lyn."},
  "e2": {"Fordi felles jordfeilbryter er forbudt i alle anlegg, og NEK krever egen automat på hver kurs uansett størrelse":"Det er ikke grunnen til egne vern. Med én felles jordfeilbryter går alle kursene ut ved én feil.","For å spare plass i tavla, siden én jordfeilbryter kan erstatte alle automatene uten å endre selektiviteten":"En jordfeilbryter beskytter ikke mot overlast og kortslutning, så automatene trengs. Selektivitet er grunnen, ikke plass.","Fordi jordfeilautomater ikke trenger å testes, og da holder det med én felles enhet for hele tavla":"Testing har ingenting med antall vern å gjøre. Egne vern gir selektivitet, så feilen kobles bare ut der den er."},
  "e3": {"B løser ut momentant ved 5–10 × In, og C ved 3–5 × In. B tåler høyere innkoblingsstrøm, og B-vernet passer derfor best til motorkurser":"Dette er byttet om. B løser ut momentant ved 3–5 × In, og C ved 5–10 × In. Det er C som tåler mer innkoblingsstrøm.","B og C løser ut momentant ved samme verdi, 3–5 × In. Forskjellen ligger i merkingen på dekselet, og vernene har samme innkoblingsstrøm og feilstrøm":"B og C har ulik verdi for momentan utløsning, ikke samme verdi. C løser ut ved 5–10 × In, og B ved 3–5 × In.","C løser ut momentant ved 3–5 × In, og B ved 10–20 × In. C er derfor den som tåler minst innkoblingsstrøm av de to, og trenger mindre feilstrøm":"Tallene er feil. B løser ut ved 3–5 × In, og C ved 5–10 × In, så C tåler mer innkoblingsstrøm."},
  "e4": {"Jordfeilbrytere (strømstyrt vern)":"Jordfeilbrytere måler lekkasjestrøm og har ikke en tråd som brenner av. Disse elementene har smeltetråd, og den brenner av ved overstrøm.","Automatsikringer (termisk vern)":"Automatsikringer har ikke en tråd som brenner av. De kobler ut med en mekanisme og kan slås på igjen, mens disse må byttes.","Overspenningsvern (type 2) i tavla":"Overspenningsvern beskytter mot korte spenningstopper, ikke mot overstrøm. Disse elementene er smeltesikringer, og de må byttes når de har brent av."},
  "e5": {"J.F.B. er hovedbrytere (bryter alle poler), F er sikringer for lys og stikk":"J.F.B. er ikke hovedbrytere. Det er et jordfeilvern, og det beskytter ikke mot overlast eller kortslutning alene.","J.F.B. er bygget for 400 V i trefase, og F er bygget for 230 V i enfase anlegg":"Forskjellen er ikke spenningen. J.F.B. gir jordfeilvern, mens F gir overstrømsvern.","Det er to navn på samme vern, bare merket ulikt av produsentene og brukt i ulike tavler i huset":"Det er to ulike vern, ikke to navn på samme ting. J.F.B. reagerer på jordfeil, og F reagerer på overstrøm."},
  "s1": {"Nøytralpunktet er direkte jordet med PEN-leder hele veien, så jordfeil gir stor feilstrøm":"Dette er et nett med felles PEN-leder hele veien, ikke et IT-nett. I IT er nettet isolert fra jord, så én jordfeil gir liten strøm.","Anlegget har ingen beskyttelsesleder, så berøring av kapslingen er ufarlig":"Det er feil. Berøring av en kapsling kan gi farlig støt, og den må beskyttes også i IT-anlegg.","Det brukes bare i høyspenningsanlegg, og nettet er jordet i begge ender":"Dette er feil. IT-nettet i oppgaven er et lavspenningsnett på 230 V, og det er isolert fra jord, ikke jordet i begge ender."},
  "s2": {"Den kobles til PE, og N-lederen kobles bort":"Dette er feil. N-lederen kobles ikke bort, og PEN deles i to separate ledere, PE og N.","Den føres videre som felles PEN helt ut til utstyret":"PEN er felles bare en del av veien, ikke helt ut til utstyret. Etter oppdelingen må PE og N aldri kobles sammen igjen.","Den kobles til jordfeilbryteren som en fase":"PEN er ikke en fase, så den skal ikke kobles som en. I TN-C-S deles den i PE og N."},
  "s3": {"Lys blå":"Lys blå er fargen på N, nøytrallederen. PE skal ha grønn/gul, ikke lys blå.","Brun/svart":"Brun og svart er faselederne, altså de som gir spenning. De er ikke for beskyttelse.","Svart/grå":"Svart og grå brukes også til faser, så de er ikke for PE. PE har sin egen farge."},
  "s4": {"Grønn/gul":"Grønn/gul er PE, beskyttelseslederen. Nøytralen skal ikke ha den fargen.","Brun":"Brun er normalt fase, altså L. Den skal ikke brukes på nøytralen.","Grå":"Grå brukes normalt til faser, ikke til nøytralen. Fasene er brun, svart og grå, så grå er en fase."},
  "s5": {"PE og N er felles hele veien fra transformator til uttak, uten egen jordelektrode":"Dette beskriver et nett der PE og N er felles, ikke TT. I TT er det en egen jord for anlegget.","Ingen deler av anlegget er jordet, og nettets nøytralpunkt er isolert fra jord":"Dette er IT, ikke TT. I TT er nettets nøytralpunkt jordet, og det er det som skiller TT fra IT.","Anlegget bruker nøytralen i forsyningsnettet som jord, og PE er isolert fra jord":"I TT jordes ikke anlegget via nøytralen i forsyningsnettet. De utsatte delene er koblet til en egen, separat jordelektrode."},
  "s6": {"Redusere strømregningen ved å holde metalldeler i rommet på lavere spenning enn nettet, slik at mindre strøm forbrukes":"Det har ingenting med strømregningen å gjøre. Utjevningen gjør at ledende deler får samme potensial, så farlig spenning ikke oppstår.","Øke kortslutningsstrømmen i hele anlegget, slik at fremmede deler kan brukes som ledere for strøm":"Potensialutjevning skal ikke gjøre fremmede deler til strømledere. Den skal hindre farlig spenning mellom delene.","Erstatte jordfeilbryteren, slik at kursene kan ha lengre kabler uten krav til vern og jordingsmotstand i anlegget":"Utjevning erstatter ikke vern eller jordfeilbryter. Den gir heller ikke lengre kabler uten krav til vern."},
  "s7": {"Å koble ut hele anlegget straks en kurs blir overbelastet, slik at kabler og utstyr ikke overopphetes":"Det er overstrømsvernets jobb, ikke isolasjonsovervåkerens. Den varsler jordfeil, og kobler ikke ut ved overlast.","Å måle spenningsfallet på kursene og varsle når det blir for stort i forhold til kabelens lengde":"Den måler ikke spenningsfall. Isolasjonsovervåkeren ser etter jordfeil i IT-anlegget, og varsler om den.","Å styre lys og andre forbrukere automatisk etter tidsur og bevegelse i rommet":"Dette er en styringsjobb, ikke overvåking av jordfeil. Isolasjonsovervåkeren varsler bare om jordfeil."},
  "i1": {"Beskyttelse mot vann og fuktighet, altså mot sprut og regn":"Dette er det andre sifferet, som gjelder vann. Første siffer gjelder faste stoffer og berøring.","Maks spenning som kapslingen tåler, angitt i volt":"IP-koden sier ikke noe om spenning. Den viser beskyttelse mot faste stoffer og vann.","Brannklasse, der tallet viser hvor lenge det tåler brann":"IP-koden sier ikke noe om brann. Den handler om støv, berøring og vann, ikke hvor lenge noe tåler brann."},
  "i2": {"Vanntett ved neddykking":"Neddykking hører til IPX7, ikke IPX4. IPX4 tåler sprut fra alle kanter, men ikke at utstyret står under vann.","Ingen beskyttelse mot vann":"Det er feil. Tallet 4 viser en vannbeskyttelse, så det finnes en beskyttelse.","Beskyttet mot dryppende vann loddrett":"Loddrett dryppende vann er et lavere nivå enn 4. Tallet 4 gir mer beskyttelse, nemlig mot sprut fra alle retninger."},
  "i3": {"Fordi spenningen i kursen er dobbel av 230 V":"Spenningen i kursen er ikke dobbel. Faktor 2 kommer av at strømmen går to veier, fram og tilbake.","Fordi kobberlederen har dobbel resistans":"R i formelen er resistansen i én leder. Det er ikke lederen som har dobbel resistans, men strømmen som går to veier.","Det er en fast sikkerhetsmargin i NEK 400":"Faktor 2 er ikke en sikkerhetsmargin. Den kommer av at strømmen går i to ledere, fram og retur."},
  "i4": {"Bruke lengre kabel":"Lengre kabel gir mer resistans og større spenningsfall, ikke mindre. Det gjør problemet verre.","Velge en mindre sikring":"En mindre sikring endrer ikke resistansen i kabelen. Spenningsfallet blir like stort, og kursen kan bare løse ut tidligere.","Bruke aluminium i stedet for kobber med samme tverrsnitt":"Aluminium leder strøm dårligere enn kobber. Ved samme tverrsnitt gir det høyere resistans og større spenningsfall."},
  "i5": {"Den øker, fordi tette kabler kjøler hverandre":"Det er feil. Tette kabler varmer hverandre opp, og dårligere varmeavgivelse gir lavere belastbarhet.","Den er uendret, legemåten påvirker ikke varmen":"Legemåten påvirker varmen mye. Dårligere varmeavgivelse gjør at kabelen må ha lavere belastning.","Den dobles når kablene ligger tett i samme rør":"Belastbarheten dobles ikke. Når kablene ligger tett, blir varmen verre, og belastbarheten må ned, ikke opp."},
  "i6": {"Sone 1":"Sone 1 ligger over innsiden av karet, ikke i den. Innsiden av karet er en egen sone, og den er lavere enn sone 1.","Sone 2":"Sone 2 ligger rundt karet, og den er ikke innsiden. Innsiden av karet er en egen sone, og den er ikke sone 2.","Utenfor sonene":"Innsiden av karet er ikke utenfor sonene. Den er den innerste og strengeste sonen i badet."},
  "i7": {"Den øker":"Det er feil. Varmere omgivelser gir dårligere kjøling, og kabelen tåler mindre strøm, ikke mer.","Den påvirkes ikke":"Det stemmer ikke. Omgivelsestemperaturen har betydning, og det tas hensyn til med en korreksjonsfaktor.","Den øker litt, fordi varm kobber leder bedre":"Kabelen blir ikke bedre av varme. Når kjølingen er dårligere, må strømmen ned, ikke opp."},
  "bf5": {"Faselederen":"Fasen kobles til ett av hullene i stikkontakten, ikke til de metalliske klemmene på sidene. Klemmene på sidene er for jord.","Nøytrallederen":"Nøytralen kobles til ett av hullene, ikke til de metalliske klemmene på sidene. Klemmene er for jord, ikke for nøytral.","Kontakter for barnesikringen":"Klemmene på sidene er ikke for barnesikring. De er for jordtilkobling, og får kontakt fra jordbøylene på støpselet."},
  "bf6": {"Den er for 380–480 V (vanlig 400 V)":"Rød er for 380–480 V, ikke blå. Blå er for spenningen 200–250 V, som ligger rundt 230 V.","Den er for 100–130 V (vanlig 110 V)":"Gul er for 100–130 V, ikke blå. Blå passer til 200–250 V, som er et høyere område.","Den er bare for utendørs bruk (IP67)":"Fargen forteller spenningen, ikke om kontakten tåler vann. Blå betyr 200–250 V, og utendørs bruk er et annet forhold."},
  "bf7": {"3-fase 400 V med nøytral":"En 3-fase kontakt har fem kontakter (L1, L2, L3, N, PE) eller fire uten N. Denne har bare L1, N og PE.","Likestrøm 24 V":"Kontakten har L1 og N, som brukes til vekselspenning, ikke likestrøm. Den passer til vanlig vekselspenning med jord.","SELV-krets på bad":"SELV er ekstra lav spenning, høyst 50 V AC eller 120 V DC. Denne kontakten har L1 og N, og er ikke for SELV."},
  "e13": {"Bryteren er beregnet for høyst 250 A og 10 V likespenning":"Dette er byttet om. 10 er strømmen i A, og 250 er spenningen i V, ikke omvendt.","Den tåler 250 A ved 10 V, og skal ikke brukes med vern over 16 A":"Dette er feil. 10 er høyeste strøm i A, og 250 er spenning i V, ikke 250 A ved 10 V.","Den har 10 poler og 250 koblinger, og skal monteres på DIN-skinne":"10 er ikke antall poler, og 250 er ikke antall koblinger. Tallene forteller strøm i A og spenning i V."},
  "e14": {"Den er nøytrallederen og skal merkes blå, også når den er uisolert og ligger i koblingsboksen sammen med PE":"Den blanke lederen er ikke N, og den skal ikke merkes blå. N er blå, men en blank leder er PE.","Den er en faseleder og skal merkes brun, fordi den er uisolert og må skilles fra PE i boksen":"Den blanke lederen er ikke fase. Brun er fasefargen, men her er lederen PE, som er blank og uisolert.","Den er ikke i bruk og kan klippes bort, siden alle uisolerte ledere i eldre kabler skal fjernes ved oppgradering":"Den blanke lederen kan være PE, og den må ikke klippes bort. Den er viktig for jording, så den skal ikke fjernes uten sjekk."},
  "e15": {"NEK sier ingenting om farger på ledere, bare om tverrsnitt":"NEK har krav til farger: N skal være blå og PE grønn/gul, og merkingen skal følge NEK EN 60445.","L1 skal være brun, L2 svart og L3 grå, ellers er koblingen ulovlig":"NEK krever ingen bestemt rekkefølge av fasefargene. Figurene bruker svart, brun og grå, men det er ikke et krav.","Fargene bestemmer dreieretningen, så svart må kobles til L1":"Fargene viser ikke faserekkefølge. Dreieretningen må sjekkes med måler, uansett farge."},
  "e16": {"Tre stikkontakter med jord, 16 A hver, drift i 6 timer for 230 V mellom faser":"Det er ikke tre kontakter, men tre faser i én kontakt. Tallet 6h er klokkeposisjon for jorden, ikke timer.","Tre faser og nøytral med jord, 16 A, jordkontakten i klokkeposisjon 6, for 400 V":"Merkingen 3P+⏚ har ingen N. En kontakt med nøytral er merket 3P+N+⏚.","Tre faser og jord (uten nøytral), 6 A, jordkontakten i klokkeposisjon 9, for 230 V":"6 A og klokkeposisjon 9 stemmer ikke. Merkingen viser 16 A, og jorden står i klokkeposisjon 6 for 380–415 V."},
  "e17": {"Den brune faselederen (L), som gir armaturen spenning":"Fase skal ikke til jordklemmen. Brun er L, og jordklemmen skal ha PE.","Den blå nøytrallederen (N), som går tilbake til tavlen":"Blå er N, som hører til nøytralklemmen, ikke jordklemmen. Jordklemmen skal ha PE, som er blank.","Ingen, klemmen skal kobles til en faseklemme i lampeholderen":"Jordklemmen skal ikke kobles til faseklemmen. Armaturer i klasse I skal ha PE koblet til jordklemmen."},
  "k1": {"Forskrift om elektriske lavspenningsanlegg (FEL), om bygging og endring":"Dette er FEL, ikke FSE. FEL gjelder elektriske lavspenningsanlegg, og den handler om bygging og endring.","Forskrift om elektrisk utstyr og installasjonsmateriell i boliger":"FSE handler om sikkerhet ved arbeid og drift. Utstyr og materiell i boliger er ikke hva FSE står for.","Felles sikkerhetsregler for elektrikere og kontroll av elektriske anlegg":"Det er ikke en felles regel for elektrikere. Forskriften handler om sikkerheten når du arbeider på anlegg og driver dem."},
  "k2": {"Forskrift om elektriske ledninger og kabler":"Ledninger og kabler er bare deler av et anlegg. FEL står for elektriske lavspenningsanlegg som helhet.","Forskrift om elektriske høyspenningsanlegg":"Dette er feil. FEL gjelder lavspenningsanlegg, ikke høyspenningsanlegg.","Forskrift om elbillading og ladestasjoner":"FEL er ikke en forskrift bare for elbillading. Den gjelder elektriske lavspenningsanlegg generelt."},
  "k3": {"230 V":"230 V er bare vanlig boligspenning, ikke øvre grense for lavspenning. Øvre grense er mye høyere.","400 V":"400 V er ikke øvre grense. Lavspenning går høyere enn det, til et nivå som er tydelig større.","50 V AC":"50 V AC er grensen for SELV, altså en mye lavere spenning. Lavspenning går mye høyere enn det."},
  "k4": {"Kontrollere spenningsløshet → frakoble → sikre mot innkobling":"Du må først frakoble, før du gjør noe annet. Å kontrollere før frakobling er feil, for anlegget kan fortsatt være under spenning.","Jorde og kortslutte → frakoble → sikre mot innkobling → kontrollere":"Jording kommer etter kontrollen, og bare der det kreves. Først frakobler du, så sikrer du mot innkobling.","Sikre mot innkobling → jorde → frakoble → kontrollere at anlegget er spenningsløst":"Du kan ikke sikre mot innkobling før anlegget er frakoblet. Jording skal ikke gjøres før frakobling og kontroll."},
  "k5": {"For å kalibrere prøveren mot frekvensen i nettet":"Prøveren kalibreres ikke mot nettfrekvensen. Testen viser om den virker, så «ingen spenning» er til å stole på.","Fordi forskriften krever to målinger av samme punkt med ulike instrumenter":"Grunnen er ikke to målinger med ulike instrumenter. Poenget er å se at prøveren virker, både før og etter.","For å lade opp prøveren, så målingen blir sikker":"Testen lader ikke prøveren. Den viser om prøveren virker, for en defekt prøver kan vise «ingen spenning» selv når anlegget har spenning."},
  "k6": {"Det lokale arbeidstilsynet":"Arbeidstilsynet fører ikke tilsyn med elanlegg hos forbrukere. Det gjør et lokalt organ knyttet til nettselskapene.","Kommunens byggesaksavdeling":"Byggesaksavdelingen behandler byggesaker, ikke elsikkerhet. Tilsynet med elanlegg hos forbrukere er knyttet til nettselskapene.","Norsk Elektroteknisk Komite":"NEK lager normer, som NEK 400, men fører ikke tilsyn. Det lokale tilsynet er ikke NEKs oppgave."},
  "k7": {"En person med fagbrev, som kan utføre arbeid for andre uten registrering":"Fagbrev alene er ikke nok. Virksomheter som utfører arbeid for andre må være registrert hos DSB, og ha faglig ansvarlig.","En virksomhet som er meldt inn i Brreg, og som har en elektriker ansatt på deltid":"Brreg er ikke det som gir tillatelse. Virksomheten må være registrert hos DSB, og ha faglig ansvarlig.","Et firma som har meldt fra til nettselskapet før hvert oppdrag":"Melding til nettselskapet før hvert oppdrag er ikke nok. Det som kreves er registrering hos DSB og en faglig ansvarlig."},
  "k8": {"Arbeid etter at anlegget er frakoblet og jordet, der man kontrollerer at delene er spenningsløse før arbeidet starter":"Dette er arbeid på frakoblet anlegg, ikke AUS. Der er det ingen spenning, og AUS handler om å berøre spenningsførende deler.","Arbeid i et sikringsskap der man skifter en defekt automatsikring, som kan gjøres av en lærling uten opplæring":"Å skifte en sikring er ikke det som kjennetegner AUS. AUS krever særskilt opplæring, prosedyrer og verneutstyr.","Arbeid på anlegg under 50 V, der spenningen er lav nok til at særskilt opplæring ikke er nødvendig":"Det er ikke spenningen alene som avgjør dette. AUS betyr at man bevisst berører spenningsførende deler, og da kreves opplæring."},
  "k9": {"Ja, normen er en lov, og den må følges slik den står skrevet. Det er ikke lov å velge en annen løsning enn den som er beskrevet":"NEK er ikke en lov. FEL setter kravene, og normen viser bare én måte å oppfylle dem.","Ja, i boliger er normen bindende, mens næringsbygg og industri kan velge fritt uten å dokumentere sikkerheten":"Dette stemmer ikke, verken i boliger eller andre bygg. Velger du en annen løsning enn normen, må du dokumentere like god sikkerhet.","Ja, normen er bindende, og hver løsning må være slik den er beskrevet i den, uten annen vurdering av sikkerheten, også for ulike anlegg":"Normen er ikke bindende på den måten. Andre løsninger er lov, når du dokumenterer like god sikkerhet."},
  "k10": {"At kunden har betalt hele fakturaen, og at installatøren har gitt skriftlig garanti i to år":"FEL krever kontroll og prøving, og at eieren får erklæring om samsvar. DLE-godkjenning og registrering hos kommunen står ikke i kravet.","At DLE har godkjent anlegget på stedet, og at det er registrert hos kommunen før det tas i bruk":"Betaling og garanti står ikke i kravet. Kravet er kontroll, prøving og dokumentasjon til eieren.","Ingenting, hvis det er en liten jobb som eieren selv har sjekket at lysene virker":"Det er feil. Kravet gjelder også etter hver endring, og eieren må få erklæring og dokumentasjon."},
  "k11": {"Minst 1 år":"Ett år er for kort tid. Utstederen skal oppbevare kopien i fem år, ikke bare ett.","Minst 10 år":"Ti år er ikke kravet. Den som utsteder erklæringen skal oppbevare kopien i fem år.","Til anlegget rives":"Kopien for utstederen gjelder en bestemt tid, ikke så lenge anlegget står. Eieren tar vare på erklæringen så lenge anlegget finnes."},
  "k12": {"Det skal planlegges og utføres slik at kostnadene blir lavest mulig for eieren, og slik at det kan endres uten godkjenning senere":"Kostnad er ikke hovedkravet. Anlegget skal beskytte mennesker, husdyr og eiendom, og passe til den tiltenkte bruken.","Det skal planlegges av nettselskapet og godkjennes av kommunen før arbeidet starter, og følge leverandørens standardoppsett for anlegget":"Dette er ikke kravet i § 16. Paragrafen handler om å beskytte folk, husdyr og eiendom, og om at anlegget passer til bruken.","Det gjelder bare for næringsbygg og offentlige bygg, og ikke for boliger, fritidshus eller andre bygninger der folk oppholder seg":"Dette er feil. Kravet gjelder generelt, og folk, husdyr og eiendom skal beskyttes uansett type bygg."},
  "k13": {"Campingvogner er meldepliktige, og aggregater på 15 kVA er unntatt fra melding før arbeidet starter":"Det er byttet om. Campingvogner er unntatt, og aggregater på 15 kVA er for store til å være unntatt.","Anlegg under 400 V er unntatt fra melding, også i eksplosjonsfarlig område":"Spenning under 400 V er ikke hele bildet. Unntakene gjelder bare utenfor eksplosjonsfarlig område, og bare for små anlegg.","Små anlegg på lav spenning er ikke unntatt, og heller ikke mindre endringer i anlegget":"Dette er feil. Små anlegg med lav risiko er unntatt, og mindre endringer krever heller ikke melding."},
  "k14": {"Ytre påvirkninger gjelder utendørs, så innendørs anlegg trenger ikke vurderes for fukt, støv eller slag":"Det er feil. Anlegg innendørs kan også utsettes for fukt, støv og slag, og de må tåle det de utsettes for.","Det er kundens ansvar alene å vurdere ytre påvirkninger, så installatøren trenger ikke dokumentere valgene sine":"Dette er ikke riktig. FEL retter kravet mot anlegget og utstyret, ikke mot kunden alene.","Det gjelder høyspenningsanlegg, og lavspenningsanlegg skal dimensjoneres etter strøm og spenningsfall":"Det gjelder også lavspenningsanlegg, ikke bare høyspenning. Strøm og spenningsfall er viktig, men de erstatter ikke kravet til ytre påvirkninger."},
  "k15": {"Det holder å skrive det i en logg for anlegget":"En logg er ikke nok. Personskade skal meldes til tilsynsmyndigheten, og det skal skje snarest mulig.","Det meldes bare hvis noen dør, og da etter utredning":"Det er feil. Enhver personskade som elektrisitet har forårsaket skal meldes, og det skal ikke vente på utredning.","Det meldes til NEK, som gir tillatelse til å bruke anlegget igjen":"NEK lager normer og gir ikke tillatelse. Meldingen går til tilsynsmyndigheten, altså DSB."},
  "k16": {"Arbeid med og uten hansker, og arbeid i høyden eller i trange rom under spenning":"Hansker og høyde er ikke arbeidsmetoder. FSE beskriver tre metoder, og de handler om forholdet til spenningen.","Dagarbeid, nattarbeid og helgearbeid, der arbeidstid og bemanning avgjør hvilken metode som brukes":"Tidspunktet på døgnet er ikke en metode. Valget gjøres ut fra risikovurderingen før jobben.","Montasje, kontroll, feilsøking og fakturering av anlegg som allerede er i drift":"Dette er typer oppgaver, ikke metoder. Metodene beskriver hvordan du arbeider i forhold til spenningen, for eksempel på frakoblet anlegg."},
  "k17": {"Hvem som skal kjøre bilen til og fra jobben, og hvilket firma som har tatt jobben":"Bilkjøring og firmavalg er ikke med i minimumskravet. Risikovurderingen avgjør metode, utstyr og verneutstyr, og hvilke personer som brukes.","Pris, tidsbruk og hvilken leverandør som skal levere materiellet til jobben":"Pris og leverandør er ikke det risikovurderingen minst skal avgjøre. Det som avgjøres er sikkerheten: metode, utstyr og verneutstyr.","Ikke noe, risikovurderingen er frivillig og kan gjøres etter at arbeidet er ferdig og fakturert":"Det er feil. Risikovurderingen skal gjøres før arbeidet starter, og den avgjør hvordan arbeidet skal utføres."},
  "k18": {"Vernebriller og isolerende hansker, og at arbeidet utføres raskt":"Å jobbe raskt er ikke et sikkerhetstiltak. Verneutstyr alene erstatter ikke avstand, avskjerming og avsperring.","Ikke noe, hvis man er forsiktig og jobber rolig og konsentrert":"Forsiktighet alene er ikke nok. Det må markeres en sikkerhetsavstand, og arbeidet skal avskjermes eller avsperres.","Jording av hele anlegget, og at isolasjonen måles før arbeidet starter":"Jording av hele anlegget er ikke det som gjelder her. Ved arbeid nær spenningssatte deler skal avstanden markeres, og det skal avskjermes eller avsperres."},
  "k19": {"Ja, jording og kortslutning skal gjøres i lavspenning, og i høyspenning er det et valgfritt råd":"Det er byttet om. I lavspenning vurderes behovet, og i høyspenning er det et absolutt krav.","Ja, i lavspenningsanlegg over 50 V, og det gjelder også for korte måleoppdrag og enkle kurser":"Det er ikke et krav bare fordi spenningen er over 50 V. Behovet vurderes ut fra risikovurderingen i lavspenning, ikke etter spenningsnivå.","Ja, i boliger er jording og kortslutning et krav uavhengig av risikovurderingen":"Også i boliger vurderes behovet ut fra risikovurderingen. Det er ikke et fast krav uansett."},
  "k20": {"Leder for kobling":"Leder for kobling er ikke rollen for drift og vedlikehold av anlegget. Den rollen heter noe annet i FSE.","Faglig ansvarlig":"Faglig ansvarlig er knyttet til virksomheten som utfører arbeid, og er ikke rollen for drift av anlegget.","Driftsleder for høyspenning":"Driftsleder er for høyspenningsanlegg, ikke lavspenning. Lavspenning har en annen rolle for drift og vedlikehold."},
  "k21": {"Andre personer i bygget, også barn og eldre":"Personer i bygget er viktige, men de er ikke det som skal fjernes før AUS. En gnist kan tenne, så brannfaren må bort først.","Strømmåleren hos nettselskapet":"Strømmåleren er ikke det som skal fjernes før AUS. Det som skal fjernes, er faren for brann og eksplosjon.","Jordfeilvernet på kursene i tavla":"Jordfeilvernet er ikke det som skal fjernes før AUS. Faren for brann og eksplosjon må fjernes først, fordi en gnist kan tenne."},
  "k22": {"Utstyret skal starte automatisk når strømmen kommer tilbake":"Det er motsatt, for en maskin som starter av seg selv kan skade noen. Gjeninnkobling som kan gi fare skal ikke skje av seg selv.","Det stilles ikke krav, og gjeninnkobling kan gjøres fritt":"Det stilles krav, for gjeninnkobling kan gi fare. Den skal ikke gjøres fritt.","Utstyr over 2 kW skal startes manuelt etter strømbrudd":"Effekt er ikke det som avgjør dette. Det avgjørende er om gjeninnkobling kan gi fare, for eksempel for en maskin."},
  "e6": {"Et brannteppe (klasse 0, 1000 V) som skal legges over tavla ved brann, og som hindrer berøring av deler":"Dette er ikke et brannteppe. Duken er en avdekking som hindrer berøring ved arbeid nær spenningssatte deler.","Støvbeskyttelse mens tavla males, slik at støv ikke kommer inn i sikringene og klemmene ved arbeid i nærheten":"Duken er ikke støvbeskyttelse, og den skal ikke hindre støv. Den skal hindre berøring av deler som kan ha spenning.","En jordingsmatte for å jorde anlegget under arbeidet, koblet direkte til fasen, slik at ingen spenning kan oppstå":"Dette er ikke en jordingsmatte, og den skal ikke kobles til fasen. Den skal hindre berøring av deler som er spenningsførende."},
  "m1": {"230 V AC og minst 1 kΩ":"230 V AC er ikke prøvespenningen ved isolasjonsmåling. Det brukes likespenning, og 1 kΩ er tusen ganger for lavt.","1000 V DC og minst 100 MΩ":"1000 V er for høyt for en kurs inntil 500 V, og 100 MΩ er ikke kravet. Prøvespenningen skal være 500 V likespenning.","50 V DC og minst 0,5 Ω":"50 V er for lav prøvespenning, og 0,5 Ω er langt for lavt. Målingen skal ligge i megaohm, ikke i brøkdeler av en ohm."},
  "m2": {"I parallell med lasten":"Parallell er riktig for spenning, ikke for strøm. Strøm måles i serie, så instrumentet må være i kretsen.","Mellom fase og jord":"Mellom fase og jord måler du spenning, ikke strøm. Det gir feil måling, og kan gi kortslutning når instrumentet står på strøm.","Det spiller ingen rolle":"Det spiller en stor rolle. Strøm måles i serie, og spenning måles i parallell, så koblingen må være riktig."},
  "m3": {"Den måler isolasjonsresistans i kursen":"Tangen måler ikke isolasjon. Den måler strøm ved å se på magnetfeltet rundt en leder.","Den måler spenning i høyspent":"Tangen måler ikke spenning i høyspenning. Den måler strøm, og den legges rundt én leder.","Den erstatter spenningsprøveren i tavla":"Tangen erstatter ikke spenningsprøveren. Den måler strøm rundt en leder, og den viser ikke om anlegget er spenningsløst."},
  "m4": {"En faktura fra installatøren for utført arbeid, med oversikt over materiell og timer brukt":"En faktura er et regnskapsdokument, ikke en erklæring om sikkerhet. Samsvarserklæringen sier at anlegget er utført riktig.","En søknad til nettselskapet om tilknytning til nettet før anlegget tas i bruk":"En søknad om tilknytning er ikke en erklæring. Samsvarserklæringen kommer fra installatøren og viser at arbeidet er gjort riktig.","En garanti fra produsenten på utstyret, som gjelder i to år fra installasjonsdato":"Garanti fra produsent gjelder utstyret, ikke hele anlegget. Samsvarserklæringen er fra installatøren og gjelder hele anlegget."},
  "m5": {"Strømprisene i området, fordelt på dager og måneder over et år":"Strømpriser hører ikke hjemme her. Kursfortegnelsen viser hver kurs med vern, kabel og hva den forsyner.","Hvem som eier boligen og hvilke lån som er tinglyst på eiendommen":"Eierskap og lån står ikke i kursfortegnelsen. Den viser kursene i tavla, med vern, kabel og hva de forsyner.","Byggetegninger med alle vegger, dører og vinduer i målestokk 1:100":"Tegninger av vegger og vinduer er ikke kursfortegnelsen. Den er en liste over kursene i tavla, og den hører til dokumentasjonen av tavla."},
  "m6": {"At isolasjonen er god nok, og at den har høy resistans mellom fase og jord":"Dette er isolasjonsmåling, ikke kontinuitet. Kontinuitet viser om PE er hel og har lav resistans.","At spenningen er 230 V mellom fase og PE, og at den er stabil under måling":"Kontinuitetsmåling måler ikke spenning. Den måler resistans i lederen, som skal stemme med tverrsnitt og lengde.","At jordfeilbryteren løser ut på 30 mA, og at den tåler full belastning":"Dette er en prøve av jordfeilbryteren, ikke av PE. Kontinuitetsmåling viser bare om beskyttelseslederen er hel."},
  "m7": {"For å beregne strømregningen til kunden hver måned og årlig":"Strømregningen gjøres ut fra måler og forbruk. En kortslutningsmåling sier ikke noe om hva kunden bruker.","For å måle effektfaktoren i anlegget ved hver kontroll":"Effektfaktor måles ikke med kortslutningsstrøm eller sløyfeimpedans. Det er to ulike målinger.","For å finne riktig lyspære til armaturen før montering":"En lyspære velges etter armatur og lysbehov. Sløyfeimpedans sier ingenting om lyspærer."},
  "bf3": {"Isolasjonstester":"Isolasjonstester måler resistans med høy prøvespenning. Bildet viser en tang som legges rundt en leder.","Jordmotstandsmåler":"Jordmotstandsmåler måler motstand i jorda, ikke strøm i en leder. Bildet viser en tang rundt lederen.","Topolet spenningsprøver":"Topolet spenningsprøver viser om det er spenning. Den måler ikke strøm, og bildet viser en tang."},
  "bf4": {"Dobbelt så mye som laststrømmen, fordi strømmen går både i fase og nøytral og legges sammen":"Fase og nøytral går motsatt vei, så strømmene legges ikke sammen. Tangen viser derfor omtrent null.","Spenningen på kursen, altså omtrent 230 V mellom fase og nøytral i tavla":"Tangen måler strøm, ikke spenning. Spenning måles med spenningsprøver eller voltmeter.","Isolasjonsresistansen mellom fase og nøytral, som må være minst 1 MΩ":"Tangen måler strøm, ikke isolasjonsresistans. Isolasjon måles med isolasjonstester."},
  "e7": {"Fordi produsenten krever det for at garantien på vernene skal gjelde ved eventuelle feil":"Garanti er ikke grunnen til merking. Merkingen skal gjøre kurser og vern lette å finne.","For å vise hvor gamle vernene er, slik at de kan byttes ut når de blir eldre enn 20 år":"Merkingen viser ikke alder. Den viser hvilken kurs vernet hører til, og den skal stemme med kursfortegnelsen.","Merkingen er frivillig, og det er ikke noe krav i FEL eller NEK 400 om merking av vern":"Merking er ikke frivillig. Ved kontroll skal kurser og vern kunne identifiseres."},
  "o1": {"3000 o/min":"3000 o/min gjelder en motor med to poler, altså ett polpar. Her er det fire poler.","1000 o/min":"1000 o/min gjelder en motor med seks poler, altså tre polpar. Her er det fire poler.","750 o/min":"750 o/min gjelder en motor med åtte poler. Her er det fire poler, altså to polpar."},
  "o2": {"Bytter om alle tre fasene":"Bytter du alle tre i ring, går dreiefeltet fortsatt samme vei. Det er nok å bytte to av dem for å snu dreiefeltet.","Kobler om fra stjerne til trekant":"Stjerne og trekant endrer spenningen på viklingene, ikke retningen. Motoren går samme vei.","Bytter om fase og N på én vikling":"Nøytral skal ikke være med for å snu motoren. Det er to faser som må byttes om."},
  "o3": {"Øke turtallet":"Turtallet bestemmes av frekvens og antall poler. Stjerne/trekant er bare en startkobling.","Spare kabel":"Kabelen må tåle motorens strøm uansett kobling. Stjerne/trekant sparer ikke kabel.","Gi høyere startmoment":"Stjerne gir lavere startmoment, ikke høyere. Det er en bivirkning av lavere startstrøm."},
  "o4": {"Lynnedslag i ledningsnettet":"Lynnedslag er overspenning. Et termisk motorvern reagerer på varme fra lang overbelastning.","Jordfeil på 30 mA i kursen":"En jordfeil på 30 mA er jordfeilvernets oppgave. Motorvernet reagerer på varme fra for høy strøm.","Feil rotasjonsretning":"Motorvernet bryr seg ikke om retningen på motoren. Feil retning rettes ved å bytte to faser."},
  "o5": {"Ved å endre spenningen alene, uten å røre frekvensen":"Turtallet følger frekvensen. Ved å bare endre spenningen blir turtallsendringen liten.","Ved å bytte to av de tre fasene, som bare snur retningen":"Å bytte to faser snur bare retningen. Det endrer ikke turtallet.","Ved å bremse mekanisk på akselen med en friksjonsbrems":"Mekanisk brems er ikke regulering med omformer. Omformeren styrer turtallet med frekvens og spenning."},
  "o6": {"En type sikring som brenner over ved overlast, og som må byttes når den er utløst":"Dette er en sikring, ikke en kontaktor. En kontaktor styres av en spole og kan slå av og på mange ganger.","En kabelskjøt for å koble sammen to kabler i samme boks uten bevegelige deler":"En kabelskjøt har ingen spole og ingen bevegelige deler. En kontaktor har en spole som styrer kontaktene.","Et måleinstrument som måler effekt og energiforbruk i kursen":"Det er ikke et måleinstrument. En kontaktor brukes til å koble laster, ikke til å måle effekt."},
  "o7": {"At motoren går fortere enn synkront turtall, altså over dreiefeltet":"Rotoren går alltid litt saktere enn dreiefeltet i en asynkronmotor. Den går ikke fortere.","At remmen slurer på motorakselen og gir mindre moment på drivhjulet":"Det er sakking inne i motoren, ikke at en rem slurer. Remslur er et eget problem utenfor motoren.","At motoren står stille, fordi rotoren er låst og strømmen er null":"Med låst rotor er sakkingen 100 %. Strømmen blir høy, ikke null."},
  "o8": {"Kontakten er lukket i hvilestilling og åpner når den påvirkes":"Dette er en brytekontakt, NC. NO er åpen i hvilestilling og slutter når den påvirkes.","Kontakten er åpen i hvilestilling og åpner også når den påvirkes":"En kontakt som er åpen i hvile, åpner ikke når den påvirkes. NO slutter kretsen.","Kontakten veksler mellom to kretser når den påvirkes":"Dette er en vekslerkontakt med to kretser. NO har bare én krets, og den slutter kretsen."},
  "sym1": {"Bryter, topolet":"Topolet bryter har to streker på armen. Dette symbolet har bare én strek, så det er enpolet.","Enpolet bryter med tidsbegrenset innkobling (trappeautomat)":"Trappeautomat har bokstaven t ved symbolet. Her er det ingen t, så lyset slukker ikke av seg selv.","Trykknappbryter":"Trykknapp har en ring i en sirkel. Dette symbolet har en arm og ingen sirkel."},
  "sym2": {"Bryter, enpolet":"Én strek på armen betyr enpolet. Her er det to streker, så den bryter to ledere.","Tre enpolede brytere i samme armatur":"Tre brytere i samme armatur vises med tallet 3. Her er det to streker på armen, ikke tre brytere.","Belysningsregulator (dimmer)":"Dimmer har en skråstrek eller trekant for regulering. Her er det to streker og ingen regulering."},
  "sym3": {"To enpolede brytere i samme armatur":"Tallet ved symbolet viser antall brytere. Det er tre brytere, ikke to.","Topolet bryter, styrt fra to steder":"To streker på armen betyr topolet. Symbolet her viser flere brytere i samme armatur.","Stikkontakt, trepolet, for tre faser":"Stikkontakt har en bue, ikke armer med brytere. Dette symbolet er brytere, ikke en stikkontakt."},
  "sym4": {"Vekselvender (tidligere endevender)":"Vekselvender har én arm opp og én ned. Her er det to armer opp, til hver sin side.","Kryssvender (tidligere mellomvender)":"Kryssvender har fire armer. Dette symbolet har bare to armer.","Bryter, topolet (bryter to ledere)":"Topolet bryter har to streker på én arm. Her er det to armer som peker opp, til hver sin side."},
  "sym5": {"Serievender (tidligere kronevender)":"Serievender har to armer opp, til hver sin side. Her er det én arm opp og én ned.","Kryssvender (tidligere mellomvender)":"Kryssvender har fire armer. Dette symbolet har bare to armer.","Bryter, enpolet (vanlig av/på)":"En vanlig enpolet bryter har én arm. Her er det to armer, én opp og én ned."},
  "sym6": {"Vekselvender (tidligere endevender)":"Vekselvender har to armer, én opp og én ned. Kryssvender har fire armer.","Serievender (tidligere kronevender)":"Serievender har to armer opp, til hver sin side. Kryssvender har fire armer.","Tre enpolede brytere i samme armatur":"Tre brytere i samme armatur vises med tallet 3 ved symbolet. Dette symbolet har fire armer."},
  "sym7": {"Bryter, enpolet":"En vanlig enpolet bryter har ingen snor og ingen pil nedover. Pilen viser at du trekker i snor.","Trykknappbryter":"En trykknapp betjenes med trykk, ikke med snor. Her er det en pil nedover, som viser snor.","Enpolet bryter med tidsbegrenset innkobling (trappeautomat)":"Trappeautomat har bokstaven t ved symbolet. Pilen viser snor, ikke tidsfunksjon."},
  "sym8": {"Trykknapp (én stabil stilling)":"En ren trykknapp har ikke arm, og den fjærer tilbake. Her er det en arm, som viser at det er en bryter.","Bryter, enpolet":"En enpolet bryter har bare en arm og ingen ring i en sirkel. Her er det en ring i en sirkel.","Trykknapp med indikatorlampe":"Indikatorlampe vises med kryss i sirkelen. Dette symbolet har ring og arm, men ikke kryss."},
  "sym9": {"Enpolet bryter med tidsbegrenset innkobling (trappeautomat)":"Trappeautomat har bokstaven t. Dimmer har en skråstrek som viser regulering.","Bryter, topolet":"Topolet bryter har to streker på armen. Dimmer viser regulering, ikke antall ledere.","Bryter, enpolet":"Enpolet bryter er bare av og på, uten regulering. Skråstreken betyr at lysstyrken kan justeres."},
  "sym10": {"Belysningsregulator (dimmer) for trinnløs styring av lysstyrken":"Dimmer har skråstrek for regulering av lysstyrke. Her står det bokstaven t, som viser tidsfunksjon.","Bryter, enpolet, med fast stilling og manuell av/på-funksjon":"Dette har en tidsfunksjon, ikke bare manuell av og på. Bokstaven t viser at lyset slukker av seg selv.","Dobbeltpolet bryter med tidsbegrenset innkobling (trappeautomat)":"Det er en enpolet bryter, med én strek på armen. Dobbeltpolet ville bryte to ledere."},
  "sym11": {"Trykknapp med indikatorlampe":"Indikatorlampe vises med kryss i sirkelen. Dette symbolet har bare ring, uten kryss.","Trykknappbryter":"Trykknappbryter har arm i sirkelen. Her er det bare en ring uten arm.","Stikkontakt, topolet uten jord":"Stikkontakt har en bue, ikke en ring. Dette er en knapp, ikke et uttak."},
  "sym12": {"Trykknapp (én stabil stilling)":"Uten kryss i sirkelen er det ingen lampe. Krysset viser at knappen har indikatorlampe.","Trykknappbryter":"Trykknappbryter har arm i sirkelen. Her er det kryss, som viser lampe.","Belysningsregulator (dimmer)":"Dimmer har skråstrek for regulering. Her er det sirkel med kryss, som er en knapp med lampe."},
  "sym13": {"Stikkontakt, topolet med jord":"Med jord er det en strek foran buen. Her er det ingen strek, så det mangler jordkontakt.","Stikkontakt, trepolet":"Trepolet har skråstrek med tallet 3 på tilførselen. Dette symbolet har ikke det.","Stikkontakt med flere uttak (her tre)":"Tall ved buen viser antall uttak. Dette symbolet er én stikkontakt uten slikt tall."},
  "sym14": {"Stikkontakt, topolet uten jord":"Uten jord mangler streken foran buen. Her er det en strek, som viser jordkontakt.","Stikkontakt med flere uttak (her tre)":"Tallet ved buen viser antall uttak, ikke jord. Dette er én stikkontakt med jord.","Stikkontakt, trepolet":"Trepolet har skråstrek med tallet 3. Her er det en strek foran buen, som viser jord."},
  "sym15": {"Stikkontakt med flere uttak (her tre)":"Tallet ved buen viser antall uttak. Trepolet har skråstrek med tallet 3 på tilførselen.","Stikkontakt, topolet med jord":"Med jord er det en strek foran buen. Trepolet har skråstrek med tallet 3.","Tre enpolede brytere i samme armatur":"Dette er en stikkontakt med bue, ikke brytere med armer. Den har ingen tre brytere."},
  "sym16": {"Stikkontakt for trefase, med jord":"Trefase har tallet 3 på tilførselen. Tallet her viser antall uttak, ikke poler.","Stikkontakt med jord og bryter":"Jord vises med strek foran buen, og bryter med arm. Tallet ved buen viser antall uttak.","Stikkontakt med beskyttelsesdeksel":"Symbolet viser ikke et deksel. Tallet ved buen viser antall uttak i samme boks."},
  "d1": {"Velge kabeltype ut fra farge":"Farge er ikke det første. Kabelen velges først etter at strømmen er funnet.","Måle isolasjonsresistansen":"Måling er en kontroll av anlegget, ikke første steg når du dimensjonerer.","Skrive samsvarserklæringen":"Samsvarserklæringen skrives til slutt, når anlegget er kontrollert og ferdig."},
  "d2": {"Antall faser i anlegget, altså om det er 1-fase eller 3-fase tilkobling":"Antall faser er ikke samtidighetsfaktoren. Den viser hvor mye av lasten som er i bruk samtidig.","Forholdet mellom spenning og strøm i den enkelte kursen, altså impedansen":"Impedans er ikke samtidighetsfaktor. Samtidighet handler om hvor mye av lasten som brukes samtidig.","Korreksjonsfaktoren for temperatur i kabelen, som brukes ved legging i rør":"Dette er en temperaturfaktor for kabelens strømføring. Samtidighetsfaktoren gjelder bruk av lasten."},
  "d3": {"Ca. 43 A":"43 A er strømmen uten samtidighetsfaktoren. Med faktor 0,6 blir strømmen lavere.","Ca. 78 A":"78 A er regnet med 230 V. I et 400 V anlegg blir strømmen lavere.","Ca. 15 A":"15 A er for lavt. Formelen deler på √3 (ca. 1,73) og 400 V, ikke på en større verdi."},
  "d4": {"For å sikre at vernet løser ut ved små feil, slik at kabelen ikke overbelastes ved lav feilstrøm":"Her blandes det med små feil. Største kortslutningsstrøm sjekkes mot bryteevnen til vernet.","For å beregne spenningsfallet på kursen, som er det eneste som avgjør hvilket tverrsnitt som velges":"Spenningsfall er ett av flere krav. Det er ikke grunnen til å sjekke største kortslutningsstrøm.","For å velge farge på lederne i kursen, slik at det er lett å se hvilken fase som er hvilken":"Farge på lederne har ingenting med kortslutningsstrøm å gjøre. Det er bryteevnen som må sjekkes."},
  "d5": {"For å sjekke bryteevnen til vernet, som må være høyere enn største kortslutningsstrøm på kursen":"Bryteevne sjekkes mot største kortslutningsstrøm, ikke minste. Minste sjekkes for at vernet løser ut.","For å finne samtidighetsfaktoren for alle kursene i tavla, og dermed belastningen":"Samtidighetsfaktor er en belastningsvurdering. Den handler ikke om kortslutningsstrøm.","For å velge IP-grad på kabelen og sikre at den tåler fukt og støv i miljøet":"IP-grad velges etter miljøet, ikke etter kortslutningsstrøm. Det er ikke grunnen til sjekken."},
  "d6": {"Ca. 80 A (5 × In)":"5 × In er nedre grense for momentan utløsning i C-karakteristikk. For sikker utløsning brukes øvre grense.","Ca. 48 A (3 × In)":"3 × In er under nedre grense for momentan utløsning med C-karakteristikk, som er 5 × In.","Ca. 16 A (1 × In)":"1 × In er bare merkestrømmen. Vernet løser ikke momentant ved så lav strøm."},
  "d7": {"Bruker t = k² · S² / I² som vanlig, også når vernet bryter på under 0,1 s":"Den formelen gjelder for lengre tider. Under 0,1 s må du bruke vernets I²t fra datablad.","Måler temperaturen på kabelen med termoelement under kortslutningen i kursen":"Kontrollen gjøres ved beregning mot datablad. Det går ikke an å måle kabelen under en kortslutning.","Det trengs ingen kontroll, fordi vernet bryter før kabelen rekker å bli varm":"Det trengs kontroll. Vernet kan slippe gjennom energi som varmer kabelen, så den må sjekkes."},
  "d8": {"Fordi kabelen er 20 % lengre enn tegnet på tegningen, slik at feilstrømmen blir høyere":"Lengden på kabelen er ikke grunnen. Faktoren kommer av temperatur, og den gjør feilstrømmen lavere, ikke høyere.","For å ta med jordfeilvernet i beregningen av minste kortslutningsstrøm":"Jordfeilvernet har ingen rolle i denne faktoren. Den gjelder kobberets resistans ved varme.","Det er en tilfeldig sikkerhetsmargin som legges til i alle beregninger uten fysisk grunn":"Det er ikke en tilfeldig margin. Kobber får høyere resistans når det blir varmt, og det har en fysisk grunn."},
  "d9": {"A1":"A1 er kabel i rør i isolert vegg. Kabel festet rett på veggen uten rør er en annen metode.","D":"D er kabel i jord. Den er ikke festet på vegg.","E":"E er kabel i fri luft. Den er ikke festet på vegg."},
  "d10": {"I = P · cos φ / (√3 · U)":"Cos φ skal stå i nevneren, ikke i telleren. Her er den ganget opp, og det gir feil strøm.","I = P / (U · cos φ)":"Det mangler √3 for 3-fase. Uten √3 blir strømmen for stor.","I = P · √3 / (U · cos φ)":"√3 skal stå i nevneren, ikke i telleren. Her blir strømmen for stor."},
  "fp1": {"Velge farge og type på stikkontaktene og bryterne før du tegner anlegget":"Stikkontakter og brytere velges etter planen. Risikovurderingen kommer først.","Regne ut spenningsfall på kursene i tavla ut fra lengde og tverrsnitt":"Spenningsfall regnes når du vet kursene og lengdene. Det er ikke første steg.","Bestille materiell og kabler fra grossisten før du har laget en plan":"Du bør ha en plan og en vurdering før du bestiller. Ellers kan du kjøpe feil materiell."},
  "fp2": {"Arbeid under spenning, FSE § 16, som er vanlig i nye boliger fordi anlegget er åpent":"Arbeid under spenning gjøres på spenningsførende deler. I en ny bolig er anlegget normalt ikke spenningssatt.","Arbeid nær ved spenningssatte deler, FSE § 17, med avstandskrav og skjerming":"Dette gjelder når det finnes spenningssatte deler i nærheten. I en ny bolig er ikke anlegget koblet inn.","Det trengs ikke en arbeidsmetode i nye anlegg, siden spenningen ikke er koblet inn foreløpig":"Det trengs alltid en arbeidsmetode, også i nye anlegg. Arbeid på frakoblet anlegg er den vanlige."},
  "fp3": {"Fem sikringer i serie på samme strømtilførsel, som løser ut samtidig ved overlast i en bolig, og som skiftes av elektrikeren etter hver utløsning":"Dette er ikke sikringer. «5 sikre» er et begrep for dokumentasjon, ikke for vern.","Fem regler for arbeid under spenning (AUS) som NEK 400 krever før man åpner en kapsling, og som gjelder ved arbeid i anlegg over 1000 V":"Dette er ikke fem AUS-regler for høyspent. Frakoblingsstegene er noe annet, og «5 sikre» er dokumentasjon.","En type jordfeilbryter med fem poler og 300 mA utløsestrøm, som brukes i industrianlegg der det ikke finnes annen jordfeilbeskyttelse i det hele tatt":"Dette er ikke en jordfeilbryter. «5 sikre» er et sett skjemaer, ikke et vern."},
  "fp4": {"6 mm² Cu":"6 mm² kobber er minstekravet når lederen ikke ligger i jord. Lederen i jord må være større.","10 mm² Cu":"10 mm² er for lite for kobber i jord. Der kreves et større tverrsnitt.","2,5 mm² Cu":"2,5 mm² er for tynt for jordingsleder. Kobber i jord må være større enn dette."},
  "fp5": {"Minst halvparten av største faseleder i installasjonen, minst 10 mm² Cu, men trenger ikke være over 35 mm² Cu":"Det er PE-lederen som er utgangspunktet, ikke faselederen. Og 10 mm² er ikke kravet.","Minst 10 mm² Cu, uavhengig av største PE-leder i installasjonen, men trenger ikke være over 16 mm² Cu":"Tverrsnittet skal følge største PE-leder, ikke være fast. 16 mm² er ikke en øvre grense her.","Samme tverrsnitt som største faseleder, og minst 2,5 mm² Cu i fast installasjon":"Tverrsnittet følger største PE-leder, ikke faselederen. 2,5 mm² er under minstekravet på 6 mm² kobber."},
  "fp6": {"Nøytrallederen, fordi den er forbundet direkte til jordskinnen i hver kurs":"Nøytrallederen er ikke med på listen. Den skal ikke kobles til jordskinnen i hver kurs.","Faseledere, også L1, L2 og L3 fra kursene i hele anlegget":"Faseledere skal ikke kobles til jordskinnen. Lederne på listen er jord- og utjevningsledere.","Jordelektroden, som skal kobles direkte til hver stikkontakt og bryter i hele boligen, også i tavla":"Jordelektroden kobles ikke til hvert uttak. Den går til hovedjordskinnen."},
  "fp7": {"Type A":"Type A er tillatt i Norge. Den registrerer også pulserende likestrøm, ikke bare ren vekselstrøm.","Type F":"Type F er tillatt i Norge. Den er laget for blandede frekvenser, og den er ikke forbudt.","Type B":"Type B er tillatt i Norge. Den registrerer også ren likestrøm, og den er ikke forbudt."},
  "fp8": {"Den skal være under 1 Ω, uavhengig av både ledertverrsnitt og lederlengde":"1 Ω er ikke kravet i NEK 400. Målingen skal stemme med tverrsnitt og lengde, ikke med en fast grense.","Den skal være over 1 MΩ i kursene, også der lederne er lange":"1 MΩ er et krav til isolasjon, ikke til PE-kontinuitet. Kontinuitet skal vise lav resistans.","Den skal være 0 Ω, siden PE-lederen er ideell og uten motstand":"Ingen leder er helt uten motstand. Lange og tynne ledere gir en høyere måleverdi."},
  "fp9": {"Ca. 0,84 Ω":"0,84 Ω er ti ganger for høyt. Regnestykket 0,0175 · 12 / 2,5 gir 0,084 Ω.","Ca. 8,4 Ω":"8,4 Ω er hundre ganger for høyt. En PE på 12 m og 2,5 mm² har mye lavere motstand.","Ca. 0,0084 Ω":"0,0084 Ω er ti ganger for lavt. Riktig regnestykke gir 0,084 Ω."},
  "fp10": {"400 ms":"400 ms (0,4 s) er tidsgrensen for forbrukerkurser i TN 230 V. Den gjelder ikke jordfeilbryteren ved IΔn.","40 ms":"40 ms er produktkravet ved fem ganger merkeutløsestrømmen. Ved IΔn er kravet lengre.","5 s":"5 s er tidsgrensen for hovedkurser i TN. Den gjelder ikke en jordfeilbryter ved IΔn."},
  "fp11": {"cc (cm) = kabellengde (m) · 100 / areal (m²)":"Areal og kabellengde er byttet om. Da blir cc-avstanden feil.","cc (cm) = areal (m²) · kabellengde (m) / 100":"Lengden skal være i nevneren, ikke ganges med arealet. Da blir tallet ikke en avstand.","cc (cm) = 230 · areal (m²) / kabellengde (m)":"230 V er spenningen, ikke en del av avstandsformelen. Her skal 100 stå, for å gi cm."},
  "fp12": {"Spenningen i kursen, og at den er lik nettspenningen på hvert uttak i boligen":"Spenning sier ikke noe om skade på kabelen. Mål lederresistans og isolasjonsresistans.","Temperaturen i gulvet og kabelen, målt med termometer etter at gulvet er støpt":"Måling etter støping viser ikke skade fra legging. Derfor måles kabelen før og etter legging.","Ikke noe, kabelen er testet på fabrikken og trenger ikke måling etter legging":"Kabelen kan skades under legging. Derfor må den måles før og etter, ikke bare testes på fabrikken."},
  "fp13": {"For å spare kabel, slik at varmekabelen kan legges tettere i hele rommet uten å ta hensyn til møbler og sluk":"Varmefrie områder er ikke for å spare kabel. De skal gi plass til inventar, slik at det ikke stopper varmen.","Fordi varmekabel ikke kan ligge under fliser eller parkett, og fordi den må ligge tett under inventaret":"Varmekabel legges under gulvbelegg, så det er ikke grunnen. Varmefrie områder er til inventar.","Det er ikke nødvendig å planlegge noe, siden kabelen kan legges tilfeldig uten krav til avstand":"Kabelen må planlegges, og den kan ikke legges tilfeldig. Varmefrie områder viser hvor inventar står."},
  "fp14": {"Kvitteringen for kabelen og et bilde av termostaten, siden resten er skjult under gulvet":"Kvittering og bilde er ikke nok. Eieren skal ha tegninger som viser hvor kablene og følerne ligger.","Ikke noe, det er skjult under gulvet, og dokumentasjon av varmekabelen er ikke påkrevd etter installasjon i boligen":"Dokumentasjon skal gis, fordi kabelen er skjult og må finnes igjen. Det er ikke riktig at ingenting trengs.","Et bilde av termostaten på veggen, med angivelse av hvilket rom den styrer og hva den er innstilt på":"Et bilde av termostaten viser ikke hvor kabelen og følerne ligger. Det trengs tegninger."},
  "fp15": {"Det kan settes i en vanlig stikkontakt i sone 1, med en kurs uten jordfeilvern":"Boblebad klasse I skal være fast tilkoblet. En vanlig stikkontakt er ikke riktig løsning.","Det trenger ikke jordfeilvern, siden det er en fast tilkobling og dermed sikkert å bruke i sone 1":"Fast tilkobling betyr ikke at det er sikkert. Det er ikke et unntak fra beskyttelsen.","Det skal kobles til 400 V med tre faser, og bryteren skal stå i sone 0 over badekaret":"Det står ikke krav om 400 V og tre faser i denne regelen. Sone 0 er innsiden av karet, og bryteren skal plasseres etter sonekravene."},
  "fp16": {"To serievendere (tidligere mellombrytere)":"Serievender styrer to lysgrupper fra ett sted. Her er det ett lys som skal styres fra to steder.","En kryssvender alene i stedet for to brytere":"En kryssvender må stå mellom to vekselvendere. Alene gir den ikke styring fra to steder.","To enpolede brytere i parallell over gangen":"To vanlige enpolede brytere kan ikke styre ett lys fra to steder. Det trengs vekselvendere."},
  "fp17": {"Ca. 300 mA":"300 mA er for høyt for minste feilstrøm. Hjelperegelen gir en lavere verdi for 150 kVA.","Ca. 15 mA":"15 mA er for lavt. Hjelperegelen gir en høyere verdi for en trafo på 150 kVA.","Ca. 1,5 A":"1,5 A er langt over det hjelperegelen gir. Den er altfor høy."},
  "fp18": {"Merkeutløsestrømmen må være større enn strømmen som går til jord ved første feil, og være minst 300 mA":"Da løser vernet ikke ut ved første feil. Merkeutløsestrømmen skal være lik eller mindre enn feilstrømmen.","Det må være minst 1 A merkeutløsestrøm, uansett hvor stor feilstrømmen blir ved første jordfeil":"1 A er ikke et krav i IT. Vernet må være tilpasset feilstrømmen, ikke ha en fast minstegrense.","Det må være tidsforsinket 1 s og type AC, slik at vernet ikke løser ut ved korte transienter":"Tidsforsinkelse og type er ikke det som avgjør dette. Det er forholdet mellom utløsestrøm og feilstrøm."},
  "fp19": {"16 A":"16 A gir I2 = 1,3 · 16 = 20,8 A, og det er over Iz på 20 A.","20 A":"20 A gir I2 = 26 A, altså langt over Iz på 20 A.","10 A":"10 A er trygt under grensen, men det er ikke det største du kan bruke."},
  "fp20": {"Boligkravet I2 ≤ Iz gjelder for ledere i hele boligen":"Boligkravet gjelder bare ledere opp til 4 mm² kobber. En 6 mm² kabel faller utenfor.","Ekstra krav gjelder ledere over 4 mm² av aluminium":"Aluminium er ikke nevnt i spørsmålet. Det er de generelle kravene som gjelder for en 6 mm² kabel.","IB ≤ In og In ≤ 0,8 · Iz, uten krav til I2":"Kravet til I2 mangler her, men det er en del av de generelle kravene."},
  "fp21": {"Måle isolasjonen med 500 V mellom fase og PE, og kontrollere at verdien er over 1 MΩ":"Isolasjonsmåling viser isolasjon, ikke utløsning. Det er ikke en test av momentan utløsning.","Teste jordfeilbryteren med prøveknappen og kontrollere at den løser ut ved 30 mA på kursen":"Prøveknappen tester jordfeilbryteren, ikke overstrømsvernet. Det sjekker ikke momentan utløsning.","Sjekke at kabelen er 2,5 mm² og at den har tilstrekkelig bæreevne for kursen i henhold til tabell":"Bæreevne er viktig, men det viser ikke utløsning. Du må sjekke minste kortslutningsstrøm."},
  "fp22": {"ΔU = √3 · I · ρ · L / A":"√3 brukes for 3-fase. En 1-fase kurs har faktor 2, for fram- og returleder.","ΔU = I · ρ · A / L":"Areal og lengde er byttet. Lengden skal stå i telleren, arealet i nevneren.","ΔU = U · I":"U · I er effekt, ikke spenningsfall. Spenningsfall regnes ut fra ρ, lengde og tverrsnitt."},
  "fp23": {"Direkte i kursvernet, og etter NEK 400 uten samarbeid med nettselskapet":"Inntaket tilknyttes ikke i kursvernet. Nettselskapet må være med, fordi de bestemmer måleren.","I stikkontakten nærmest døra, der det er lettest tilgang for installatøren og kunden":"Inntakskabelen kobles ikke til en stikkontakt. Den kobles i tilknytningsskapet.","NEK 144, og tilknytningsskapet monteres av brukeren selv på veggen i boligen":"Brukeren skal ikke montere tilknytningsskapet selv. Det gjøres i samarbeid med nettselskapet."},
  "fp24": {"Fordi NEK krever at OV er dobbelt så stort som summen av kursene":"Det finnes ikke et slikt krav. Reserven er en faglig vurdering, ikke et fast tall.","For å redusere spenningsfallet i inntakskabelen til nesten null":"Vernets størrelse gjør ikke spenningsfallet nesten null. Det er kabelen og lasten som avgjør.","Fordi et større vern gir bedre selektivitet mot jordfeilvernene":"Selektivitet er et eget tema. Reserven er til senere utvidelser, ikke for å lage selektivitet."},
  "fp25": {"En vanlig stikkontakt på stikkontaktkursen i garasjen, med 16 A overstrømsvern og vanlig jordfeilvern type AC":"En vanlig stikkontakt er ikke et godkjent tilkoblingspunkt for bil. Type AC er heller ikke tillatt i Norge.","Skjøteledning fra kjøkkenet over til bilen, koblet til en vanlig stikkontakt med 10 A sikring, og en adapter til bilens lader":"Skjøteledning og adapter er ikke et trygt ladepunkt. Ladepunktet skal være fast, med egen kurs.","En mode 2-kabel fast montert i veggen på egen kurs med vanlig jordfeilvern type AC og uten overspenningsvern":"Det mangler overspenningsvern, som ladepunktet skal ha. Type AC er heller ikke tillatt i Norge."},
  "fp26": {"300 mA jordfeilvern og kapsling beregnet for innendørs bruk":"300 mA er for høyt utendørs. Her skal det være 30 mA, og kapslingen skal være for utendørs.","Automatsikring og kapsling egnet for innendørs bruk":"Innendørs kapsling er feil ute i carport. Det mangler også jordfeilvern.","Ikke noe spesielt krav, siden 16 A-kurs er nok for motorvarmeren":"Utendørs uttak har krav om jordfeilvern og egnet kapsling. Strømstørrelsen endrer ikke det."},
  "e18": {"Stikkontakten sitter for høyt over gulvet, og det er for få uttak i rommet":"Høyde og antall uttak er ikke feilen på bildet. Feilen er rørene og lederne.","Flexrør er ikke tillatt i noen installasjoner, og det må brukes stiv rørtype":"Flexrør er ikke forbudt generelt. Feilen her er at rørene ikke går helt inn i boksen.","Ingenting, dette er riktig utført, og boksen og rørene er montert i henhold til NEK":"Det er feil. Rørene går ikke helt inn, og isolerte ledere uten kappe ligger synlige."},
  "e19": {"Boksen er for stor til at den passer i veggen, og den bør byttes ut med en mindre boks med lokk":"Boksens størrelse er ikke feilen. Feilen er at flere ledere er tvunnet og klemt sammen.","Lederne er for tynne til sikringen, og de bør byttes til et grovere tverrsnitt for god kontakt":"Tverrsnittet er ikke feilen her. Feilen er tvinning og klemming i samme klemme.","Det er riktig utført, siden lederne kan tvinnes sammen før de klemmes, og det gir god og varig kontakt selv om klemmen er liten":"Tvinning før klemming er ikke godt nok. Klemmene skal passe til antall ledere og gi varig kontakt."},
  "n41-1": {"Grunnbeskyttelse er jordfeilbryteren som kobler ut ved berøring i normal drift. Feilbeskyttelse er sikringen som beskytter mot kortslutning i kursen":"Begrepene er byttet om. Grunnbeskyttelse er isolasjon, kapsling og sperrer, ikke en jordfeilbryter.","Grunnbeskyttelse gjelder for boliger, mens feilbeskyttelse gjelder for næringsbygg med høy spenning. Valget avhenger av hvilken spenning anlegget har":"Begge gjelder alle anlegg, uansett bygning. Forskjellen er hva de beskytter mot.","Det er to navn på samme ting. Begge betyr at anlegget er trygt i normal drift, og at delene er jordet og tåler full spenning":"De er ikke det samme. Den ene hindrer berøring i normal drift, og den andre slår ut ved feil."},
  "n41-2": {"5 s":"5 s er for hovedkurser i TN. Forbrukerkurser med stikkontakter har kortere tid.","1 s":"1 s er grensen i TT for hovedkurser. For forbrukerkurs i TN 230 V er tiden kortere.","0,04 s":"0,04 s er ikke grensen i tabell 41A. Tidsgrensen der er ti ganger lengre."},
  "n41-3": {"Inntil 0,4 s":"0,4 s er tidsgrensen for forbrukerkurser med stikkontakter, ikke for hovedkurser.","Inntil 0,1 s":"0,1 s er ikke tidsgrensen for hovedkurser. Den største tillatte tiden er 5 s.","Inntil 60 s":"60 s er langt over grensen. For hovedkurser i TN er største tid 5 s."},
  "n41-4": {"Ia ≥ U0 / Zs":"Ulikheten er snudd. Feilstrømmen U0/Zs må være minst like stor som Ia, ikke mindre.","Zs ≥ U0 / In":"Zs og In er blandet sammen, og ulikheten er feil. Zs må holdes lav nok for utkobling.","Ia ≤ In":"Ia er strømmen som gir utkobling innen kravtiden. Den er normalt større enn merkestrømmen, ikke mindre."},
  "n41-5": {"230 V AC eller 325 V rippelfri DC":"230 V er vanlig nettspenning, ikke ekstra lav spenning. Grensene er 50 V AC og 120 V DC.","25 V AC eller 60 V rippelfri DC":"25 V AC og 60 V DC er ikke øvre grense. Grensene er 50 V AC og 120 V DC.","100 V AC eller 200 V rippelfri DC":"100 V AC er over grensen for vekselspenning. 200 V DC er over grensen for likespenning."},
  "n41-6": {"SELV har høyere spenning enn PELV, og SELV-kretsen kan jordes ved behov i anlegget":"Spenningen er ikke forskjellen. SELV-kretsen skal ikke ha jordforbindelse, så den kan ikke jordes.","SELV krever jordfeilbryter, mens PELV ikke gjør det, og begge må jordes":"Begge må ikke jordes. SELV skal ikke ha jordforbindelse, og forskjellen er jording, ikke jordfeilbryter.","PELV brukes bare i likestrømsanlegg, og SELV-kretsen skal jordes i ett punkt":"PELV er ikke bare for likestrøm. SELV skal ikke jordes, mens PELV kan jordes."},
  "n41-7": {"Det har jordet metallkapsling, og det skal kobles til beskyttelsesleder for sikker bruk":"Dette er klasse I, ikke klasse II. Klasse II har ikke jordet kapsling som skal kobles til PE.","Det skal forsynes med SELV, og det har enkel isolasjon i tillegg til jordet kapsling":"Klasse II har ikke enkel isolasjon. Den har dobbel eller forsterket isolasjon.","Det kan brukes utendørs, og det har jordet metallkapsling i de fleste utgaver":"Utendørs bruk er ikke det som definerer klasse II. Klasse II har ikke jordet metallkapsling."},
  "n41-8": {"Et metallrør fra vannverket som kommer inn i bygget, og som er en utsatt ledende del i de fleste boliger":"Vannrør utenfra er en annen ledende del, ikke en utsatt ledende del.","En faseleder uten isolasjon, som er spenningsførende også når anlegget er frakoblet fra nettet":"Faseleder er alltid spenningsførende. En utsatt ledende del er en del som kan bli spenningsførende ved feil.","En jordleder i veggen som kobler utstyret til nøytralen i tavla, og som kan berøres":"Jordlederen er ikke en del av utstyret. En utsatt ledende del er en del på utstyret som kan berøres."},
  "n41-9": {"Stikkontakter over 63 A, og stikkontakter inntil 32 A i boliger er unntatt kravet, siden de har egen kurs og vern":"I bolig gjelder 30 mA for alle forbrukerkurser. Det finnes ingen unntak for 32 A-uttak.","Stikkontakter til motorer og varmepumper i boliger, med egen kurs og vern på hver":"Egen kurs og eget vern er ikke et unntak fra 30 mA-kravet i bolig. Hovedregelen gjelder stikkontakter.","Stikkontakter over 32 A utendørs, og stikkontakter inntil 63 A innendørs til fast tilkoblet utstyr":"Tallene er snudd. Utendørs gjelder inntil 32 A, og 30 mA gjelder i bolig uansett."},
  "n41-10": {"Ja, den erstatter all annen beskyttelse, slik at isolasjon og PE kan utelates i kursen":"Nei. Jordfeilbryteren er en ekstra sikring. Isolasjon og PE må fortsatt være med.","Ja, men bare i IT-system der jordfeilbryteren brukes som eneste vern mot berøringsspenning":"Nei, heller ikke i IT. Jordfeilbryteren er en ekstra sikring, ikke eneste vern.","Ja, hvis kursen har B-karakteristikk og jordfeilbryteren er merket med 300 mA i stedet":"Nei. B-vern og 300 mA endrer ikke dette. Jordfeilbryteren er en ekstra sikring."},
  "n41-11": {"Utstyret kobles til en egen jordelektrode, og sekundærsiden jordes for at en jordfeil skal gi høy strøm som løser ut vernet raskt":"Her er sekundærsiden jordet. Det gir en returvei, og det er motsatt av elektrisk adskillelse.","Fase og nøytral legges i separate kabler, og utstyret jordes via nøytralen for at vernet skal løse ut raskere":"Jording via nøytralen er ikke elektrisk adskillelse. Adskillelse krever at sekundærsiden ikke er jordet.","Utstyret har to jordfeilvern i serie, og begge må løse ut ved første jordfeil for at strømmen skal kobles fra helt, uansett hvor feilen er":"To jordfeilvern i serie er ikke adskillelse. Metoden bygger på at det ikke finnes returvei via jord."},
  "n41-12": {"Ca. 1 667 Ω":"1 667 Ω gjelder 30 mA. Ved 300 mA er grensen ti ganger lavere.","Ca. 15 Ω":"15 Ω er ikke største verdi. Den passer med ca. 3 A, og ved 300 mA er største verdi høyere.","Ca. 6 Ω":"6 Ω passer med ca. 8 A, ikke 300 mA. Den er ikke største verdi for 300 mA."},
  "n41-13": {"IP00 (ingen)":"IP00 gir ingen beskyttelse mot berøring. En finger kan nå spenningsførende deler.","IP1X (IPXXA)":"IP1X (IPXXA) stopper bare håndbaken og store deler. En finger kan fortsatt nå inn.","IPX4 (IPX2)":"IPX-tallet viser vern mot vann, ikke berøring. Berøringsvern er IP2X eller IPXXB."},
  "n41-14": {"Å øke spenningen i anlegget der det er mange kurser, slik at utstyret får nok spenning på hvert punkt":"Tilleggsutjevning er et sikkerhetstiltak. Den øker ikke spenningen i anlegget, og den gir ikke mer spenning til utstyret.","Å erstatte hovedjordskinnen i tavla, slik at man slipper å koble kurser og utsatte deler til PE hver for seg i hele anlegget":"Tilleggsutjevning erstatter ikke hovedjordskinnen. Den kommer i tillegg til den, og brukes lokalt på bestemte steder.","Å koble nøytrallederen til jord i hvert rom, slik at stikkontakter får samme potensial som PE-lederen":"Dette er ikke formålet. Tilleggsutjevning binder sammen utsatte og andre ledende deler, ikke nøytralleder og jord."},
  "n41-15": {"Det holder med en lampe som lyser, slik at montøren ser feilen i tavla og kan vurdere videre":"En lampe som lyser er ingen beskyttelse. Feilen må kobles ut eller beskyttes med 30 mA-vern, ikke bare vurderes videre.","De skal kobles ut først etter 24 timer, når feilen er meldt til nettselskapet":"24 timer er ingen kravtid. Feilen kan være farlig lenge før den blir meldt, og den må kobles ut i tide.","De kan stå inne ved første jordfeil, så lenge lyset og resten av anlegget virker som vanlig":"En jordfeil skal ikke bare la lyset virke. En stående jordfeil gir økt fare for alle som er koblet til samme IT-nett."},
  "n41-16": {"Inntil 5 s":"5 s er tiden for hovedkurser i TN. TT har strengere krav, så 5 s er for lang tid her.","Inntil 0,4 s":"0,4 s er kravet for forbrukerkurser i TN, ikke for hovedkurser. Hovedkurser i TT har et eget krav.","Inntil 10 s":"10 s er langt over kravet for hovedkurser i TT. Der er grensen mye lavere, og 10 s er for lang tid."},
  "n41-17": {"230 V AC (400 V DC)":"For høy spenning. Ved første feil uten utkobling kan man bare godta opp til 50 V AC. Over det må feilen kobles ut.","25 V AC (60 V DC)":"25 V AC er ikke største verdi. Største tillatte berøringsspenning ved første feil er 50 V AC, altså høyere.","12 V AC (30 V DC)":"12 V AC er en svært lav spenning. Den er ikke grensen for første feil i et IT-anlegg. Grensen er høyere."},
  "n43-1": {"Kabelens strømføringsevne skal være mindre enn eller lik vernets merkestrøm, som igjen skal være mindre enn eller lik dimensjonerende strøm":"Rekkefølgen er helt snudd. Kabelen må tåle mer enn vernet, og vernet må tåle mer enn belastningen.","Vernet skal være minst dobbelt så stort som kabelen, og dimensjonerende strøm skal være større enn både vernets merkestrøm og kabelens strømføringsevne":"Det finnes ikke krav om dobbel størrelse. Belastningen skal være lavest, og vernet skal ligge mellom belastning og kabel.","Belastningen skal være større enn vernets merkestrøm, og vernets merkestrøm skal være større enn kabelens strømføringsevne etter korreksjon":"Også her er ulikhetene snudd. Kravet er at belastningen ikke er større enn vernet, og vernet ikke større enn kabelen."},
  "n43-2": {"Kortslutningsstrømmen i kursen, som er lik den nominelle strømmen":"Kortslutningsstrømmen er mye høyere enn merkestrømmen, ikke lik den. Den er ikke det som menes med I2 her.","Strømmen i nøytrallederen ved symmetrisk last, altså ingen strøm":"Ved symmetrisk last går det ingen eller lite strøm i nøytralen. Det har ingenting med I2 å gjøre.","Startstrømmen til en motor, som er ca. 6 ganger merkestrømmen":"Startstrømmen til en motor er et annet tall. I2 gjelder vernets utløsning innen fastsatt tid, ikke motorstart."},
  "n43-3": {"20 A":"20 A er høyere enn kabelens 17 A. Da kan kabelen bli overbelastet før vernet løser ut.","10 A":"10 A er lavere enn belastningen på 13 A. Vernet ville løst ut hele tiden, selv når alt er normalt.","25 A":"25 A er langt over kabelens 17 A. Kabelen ville ikke vært beskyttet mot overbelastning."},
  "n43-4": {"Lik vernets merkestrøm, slik at vernet løser ut ved samme strøm som det er merket for":"Merkestrøm og bryteevne er to forskjellige ting. Bryteevnen må være stor nok til å bryte kortslutningen.","Halvparten av den største kortslutningsstrømmen der vernet står, siden den da blir lavere":"Kortslutningsstrømmen blir ikke lavere av seg selv. Vernet må klare hele den største strømmen som kan komme.","Lik belastningsstrømmen i kursen, slik at vernet løser ut ved overlast":"Belastningsstrømmen er normal drift, ikke kortslutning. Bryteevnen må være stor nok for den største kortslutningsstrømmen."},
  "n43-5": {"At spenningsfallet er lite nok, altså under 3 % for lys":"Spenningsfall er en egen kontroll. Uttrykket handler om hvor raskt vernet bryter en kortslutning.","At jordfeilvernet løser ut innen 0,4 sekunder i TN-systemet":"Dette handler ikke om jordfeilvern eller 0,4 sekunder. Uttrykket sjekker kortslutning i ledningen.","At kabelen tåler belastningsstrømmen i normal drift og er tilkoblet riktig":"Det er ikke belastning i normal drift som sjekkes her. Uttrykket sjekker bare hvor raskt en kortslutning brytes."},
  "n43-6": {"Ca. 0,8 s":"Formelen gir ca. 0,083 s for 2,5 mm² og 1 000 A. 0,8 s er ti ganger for lang tid.","Ca. 8 s":"Ved 1 000 A er tiden ca. 0,083 s, ikke 8 s. Tallet er altfor høyt.","Ca. 0,008 s":"0,008 s er ti ganger for kort tid. Med 2,5 mm², k = 115 og 1 000 A blir tiden ca. 0,083 s."},
  "n43-7": {"Når kabelen er kort og tilgjengelig, slik at det er enkelt å bytte sikringen ved overlast":"Kort og lett tilgjengelig kabel er ikke grunnen. Automatisk utkobling skal bare fravikes når utkobling gir større fare.","I alle boliger der det er installert jordfeilbryter og overspenningsvern på hver kurs":"Jordfeilbryter og overspenningsvern gjør ikke overstrømsvern unødvendig. Slike vern er ikke grunnen til å unnta en kurs.","Når kursen har jordfeilvern og er beregnet for tilkobling av stikkontakter i kjøkkenet":"Stikkontakter i kjøkkenet er vanlige kurser. Et jordfeilvern gjør ikke at utkobling kan utelates."},
  "n43-8": {"Sikring for motorer (aM) som bare beskytter mot kortslutning og ikke overlast":"aM er for motorer, og den beskytter bare mot kortslutning. gG er for generell bruk, og gjelder også overlast.","Sikring for likestrøm, med egen utløsekarakteristikk for batteriet":"Bokstavene gG handler om utløsning ved overlast og kortslutning. De betyr ikke at sikringen er laget for batterier.","Sikring for halvledere, som beskytter elektronikk mot kortslutning i kretser":"Halvledersikringer har egen betegnelse, ikke gG. gG er for vanlig bruk i kurser, og beskytter også mot overlast."},
  "n43-9": {"Fordi harmoniske strømmer fra fasene går i PE-lederen og ikke i nøytralen":"PE-lederen er ikke der strømmen går. Problemet kommer i nøytralen, der strømmene legger seg sammen.","Fordi elektronikk bruker likestrøm, som gir en kortslutning mellom fasene":"Elektronikk gir ikke kortslutning mellom fasene. Problemet er harmoniske strømmer, ikke likestrøm.","Det kan ikke skje, fordi nøytrallederen har samme strøm som fasene":"Det skjer. Nøytralen har ikke alltid mindre strøm enn fasene, særlig når det er mye elektronikk."},
  "n43-10": {"Midt på kabelen, slik at det er enklest å komme til vernet ved kontroll og utskifting":"Midt på kabelen er ikke et krav. Enkel tilgang er bra, men plasseringen må følge reglene for overbelastning og kortslutning.","Hvor som helst på kursen, så lenge det er tilgjengelig og merket i kursfortegnelsen":"Ikke hvor som helst. Det er regler for hvor vernet kan sitte, og merking i kursfortegnelsen alene gjør det ikke riktig.","Ved enden av kursen, der kabelen er lengst og strømmen er størst, slik at vernet ser hele kabelen":"Ved enden er ikke et fast krav. Kortslutningsvernet skal sitte i begynnelsen av kursen, ikke der kabelen er lengst."},
  "n43-11": {"To vern løser ut samtidig for sikkerhets skyld, og begge skal ha samme merkestrøm":"Back-up betyr ikke at to vern skal løse ut samtidig. Det handler om at et vern hjelper et annet med bryteevne.","Et ekstra vern i reserve på lager, som settes inn av montøren hvis hovedvernet løser ut ofte":"Reserve på lager er ikke back-up. Back-up er to vern i kursen som virker sammen ved kortslutning.","At jordfeilvernet beskytter automatsikringen mot kortslutning, og dermed erstatter bryteevnen":"Et jordfeilvern beskytter mot jordfeil, ikke mot kortslutning. Det erstatter ikke bryteevne."},
  "n43-12": {"Når kabelen er spesielt lang, fordi spenningsfallet blir for stort for en C-automat":"Lang kabel er ikke grunnen til å velge C. Spenningsfall styres av kabel og tverrsnitt, ikke av karakteristikken på automaten.","Når kursen går til bad, fordi kravene til utkobling er lavere enn ellers i boligen":"Bad har ikke lavere krav til utkobling. Valget mellom B og C handler om startstrøm, ikke om rommet.","Når man vil ha raskere utløsning ved små feilstrømmer, og velger C-karakteristikk":"C løser ut magnetisk først ved 5 til 10 ganger merkestrømmen. Den gir ikke raskere utløsning ved små feilstrømmer."},
  "n43-13": {"20 A":"20 A er lik kabelens IZ, og det er tillatt. Vernet skal ikke være større enn kabelen.","16 A":"16 A er lavere enn kabelens 20 A, så det er tillatt. Kabelen blir beskyttet.","13 A":"13 A er godt under kabelens 20 A. Det er et trygt valg for overbelastning."},
  "n43-14": {"13 A":"13 A gjelder 1,5 mm² utenfor isolert vegg. Inne i isolert vegg er største vern lavere.","16 A":"16 A er for 2,5 mm² kobber, ikke 1,5 mm². En tynnere kabel tåler ikke så høyt vern.","20 A":"20 A gjelder 4 mm² i isolert vegg. For 1,5 mm² må vernet være mye lavere."},
  "n43-15": {"20 A":"20 A gjelder 4 mm² i isolert vegg. 2,5 mm² tåler ikke så stort vern i samme situasjon.","25 A":"25 A gjelder 4 mm² utenfor isolert vegg. For 2,5 mm² er vernet mye lavere.","32 A":"32 A er over alle verdiene NEK gir for 2,5 mm². Det er for stort vern for en så tynn kabel."},
  "n43-16": {"Enpolt vern i nøytrallederen, som bryter N ved feil":"Et vern bare i nøytralen bryter ikke fasen. Da er fasen fortsatt spenningsførende, selv når bryteren er av.","Enpolt vern i fasen, og nøytralen kobles ikke ut ved feil":"Med bare fasen brutt blir nøytralen ikke koblet ut. Anlegget er da ikke sikret like godt.","Smeltesikring i PE-lederen, slik at kursen brytes ved feil":"En sikring i PE gjør at jordforbindelsen kan brytes. Da mister man beskyttelsen mot jordfeil."},
  "n43-17": {"Ved lite last i kursen, også når nøytrallederen har samme tverrsnitt som fasene":"Lav last og lik størrelse er ikke grunnen til egen deteksjon. Det som teller er hvor mye strøm N kan få.","Ikke i det hele tatt, fordi nøytrallederen ikke kan overbelastes, selv om det er store harmoniske strømmer i kursen":"Nøytralen kan bli overbelastet, særlig med store harmoniske strømmer. Den kan trenge egen deteksjon.","I IT-system, der nøytrallederen er koblet direkte til jord i hver underfordeling":"IT-systemet er ikke grunnen. Egen deteksjon avgjøres av tverrsnittet i N og av hvor store strømmer den kan få."},
  "e20": {"Vernet tåler 10 000 koblinger før det må skiftes ut, og det gjelder for både automatikken og kontakten i tavla":"Tallet ville i så fall vært antall koblinger. Men tallet i firkanten er bryteevnen i ampere.","Vernet løser ut ved 10 000 mA, og er laget for å beskytte mot jordfeil i våtrom og garasjer":"10 000 mA er ikke utløsestrøm. Et jordfeilvern har mye lavere merkeverdi, for eksempel 30 mA.","Tallet er produksjonsnummer, og vernet er merket med serienummer 10 000 på fabrikken":"Dette er ikke et serienummer. Tallet i firkanten er en teknisk verdi for bryteevne."},
  "n52-1": {"0,75 mm²":"0,75 mm² er for tynt for faste kurser til lys og kraft. Mindre tverrsnitt er bare aktuelt i signal- og styrekretser.","2,5 mm²":"2,5 mm² er mer enn minimumskravet, altså ikke det minste som er tillatt.","1,0 mm²":"1,0 mm² er under minimumet for faste kurser til lys og kraft. Det er for tynt for vanlige installasjoner."},
  "n52-2": {"4 % for belysning og 5 % for annen bruk":"4 % er høyere enn grensen for belysning. Lys har en strengere veiledende grense.","10 % for belysning og 15 % for annen bruk":"10 % og 15 % er langt over de veiledende grensene. Grensene for det allmenne nettet er mye lavere.","1 % for belysning og 2 % for annen bruk":"1 % og 2 % er ikke grensene i NEK. Grensene er veiledende og høyere enn dette."},
  "n52-3": {"Festet direkte på vegg (C), med god kjøling fra fri luft":"Kabel festet på vegg i fri luft kjøles godt. Da tåler den mer strøm, ikke mindre.","I fri luft på kabelstige (E), med plass rundt":"En kabel på kabelstige i fri luft har god plass rundt seg. Den kjøles godt, så den tåler mer strøm.","Alle gir samme strømføringsevne ved samme tverrsnitt":"Forlegningen gjør stor forskjell. Samme tverrsnitt kan tåle ulik strøm, avhengig av hvordan kabelen ligger."},
  "n52-4": {"20 °C":"20 °C er referansen for kabler i jord, ikke for kabler i luft.","40 °C":"40 °C er varmere enn referansen for kabler i luft. Ved varmere luft må strømføringsevnen reduseres.","0 °C":"0 °C er ikke referansen i tabellene for kabler i luft. Referansen er en varmere temperatur."},
  "n52-5": {"70 °C":"70 °C er grensen for PVC, ikke for PEX. PEX tåler mer.","60 °C":"60 °C er lavere enn det PEX tåler. Da ville strømføringsevnen blitt for lav.","120 °C":"120 °C er for høyt for PEX i normal drift. Over den grensen tåler ikke isolasjonen lang tids belastning."},
  "n52-6": {"Ca. 21,8 A":"Her er bare temperaturfaktoren brukt. Den andre faktoren, for samlet forlegning, må også ganges inn.","Ca. 20,0 A":"Her er bare forlegningsfaktoren brukt. Temperaturfaktoren må også ganges inn.","Ca. 41,7 A":"Tallet blir for høyt. Korreksjonsfaktorene skal ganges med IZ, og da blir resultatet lavere, ikke høyere."},
  "n52-7": {"Korteste vei på skrå gjennom veggen for å spare kabel":"Skrå trasé gjennom veggen gjør det vanskelig å finne kabelen. Andre kan ikke forutse hvor den går før de borer.","Slik det er enklest for montøren, uten merking av traséen":"Enkelt for montøren er ikke nok. Traseen skal være forutsigbar, så andre kan finne kablene senere.","I sikksakk for å unngå strekk, og med mange knekk i kabelen":"Sikksakk og mange knekk skader kabelen. Kabler i vegg skal gå rett, slik at de kan finnes igjen."},
  "n52-8": {"Ingenting, kabelen er brannsikker og kan føres gjennom veggen uten tetting":"Kabelen er ikke brannsikker av seg selv. Et hull uten tetting svekker veggens brannmotstand.","Kabelen må skjøtes på hver side av veggen, og skjøten må ligge i røret":"Skjøting er ikke løsningen her. Det som kreves er at gjennomføringen blir tettet, ikke at kabelen skjøtes.","Hullet må være minst dobbelt så stort som kabelen, og det brukes ikke tetting":"Et større hull uten tetting gir ingen brannsikring. Hullet må tettes, uansett størrelse."},
  "n52-9": {"Ja, hvis den laveste spenningen er under 50 V og har eget vern":"Lav spenning og eget vern er ikke grunnlaget. Det avgjørende er at isolasjonen tåler den høyeste spenningen.","Ja, hvis kursene kommer fra samme tavle og har samme jordfeilvern":"Samme tavle og samme jordfeilvern gjør ikke at kursene kan ligge sammen. Det som teller er isolasjonen.","Nei, kurser med ulik spenning må ligge i hver sin kabel eller rør":"Det er ikke et krav. Kurser kan ligge sammen når isolasjonen tåler den høyeste spenningen, eller kursene skilles."},
  "n52-10": {"De må ha ulikt tverrsnitt, slik at den største lederen får mest strøm og fordeles best":"Ulikt tverrsnitt gir ulik impedans. Da får én leder mer strøm, og den kan bli overbelastet.","Den ene må være av aluminium, og den andre skal være av kobber for å unngå korrosjon":"Blanding av aluminium og kobber gir ulik impedans. Da blir strømmen skjevt fordelt mellom lederne.","Det er ikke lov å parallellkoble ledere, uansett materiale, tverrsnitt eller lengde på kabelen":"Parallellkobling er ikke forbudt av seg selv. Det viktige er at lederne er like, så strømmen deler seg jevnt."},
  "n52-11": {"Omgivelsestemperatur":"Temperatur er AA, ikke AD. AD er koden for vann.","Mekanisk slag":"Mekanisk slag er AG. Det handler om støt på kabel og utstyr, ikke om vann.","Støv og fremmedlegemer":"Støv og faste fremmedlegemer er AE. Den koden gjelder ikke vann."},
  "n52-12": {"Med maling på selve kabelkappen":"Maling på kappen kan slites bort, og den gir ingen trygg merking i jorda.","Den trenger ikke merkes i det hele tatt":"Merking er viktig, så kabelen ikke blir skadet ved senere graving. Den skal merkes.","Med en ekstra kabel lagt i samme grøft":"En ekstra kabel i grøften viser ikke hvor den første ligger. Den gir ingen varsling ved graving."},
  "n52-13": {"Den øker, fordi isolasjonen beskytter kabelen":"Isolasjon beskytter ikke mot varme her. Den holder varmen inne, og da synker strømføringsevnen.","Den er uendret, fordi kabelen tåler høy temperatur":"Høy temperaturtålighet hjelper ikke her. Når varmen ikke slipper ut, må strømmen reduseres.","Den øker, fordi kabelen blir bedre beskyttet":"Bedre beskyttelse gir ikke mer strøm. Kabelen blir varmere i isolasjonen, og da må strømmen reduseres."},
  "n52-14": {"0,0175 Ω·mm²/m":"0,0175 er verdien for kobber ved 20 °C. Ved normal driftstemperatur er kobber litt høyere.","0,036 Ω·mm²/m":"0,036 er verdien for aluminium, ikke kobber. Den er høyere enn for kobber.","0,0100 Ω·mm²/m":"0,0100 er lavere enn både kobber ved 20 °C og ved driftstemperatur. Det er ikke riktig verdi for kobber."},
  "n52-15": {"At IB er minst 120 % av strømføringsevnen":"120 % betyr at kabelen blir overbelastet. Det er motsatt av det NEK anbefaler.","At IB er lik strømføringsevnen, uten noe påslag":"Null reserve gir mer varme og tap. Det er ingen plass til økt last senere.","At IB ikke overstiger 50 % av strømføringsevnen":"50 % er ikke det NEK anbefaler. Anbefalingen er en reserve, ikke at kabelen skal være så lavt belastet."},
  "n52-16": {"0,5 mm² Cu":"0,5 mm² er for tynt til 16 A. Det er langt under det NEK anbefaler for en skjøteledning.","0,75 mm² Cu":"0,75 mm² er for tynt til 16 A over 2 m. Lengre skjøteledning må ha grovere leder.","6 mm² Cu":"6 mm² er ikke minste tverrsnitt. Det er mye grovere enn det 16 A trenger."},
  "n52-17": {"Ja, hvis de ligger i samme kabel":"Samme kabel gjør ikke at de kan dele én nøytralleder. Hver hovedkurs skal ha sin egen.","Ja, hvis de har samme tverrsnitt":"Samme tverrsnitt er ikke et unntak. Hver hovedkurs skal ha sin egen nøytralleder, uansett størrelse.","Ja, i IT-system":"IT-system gir ikke noe unntak i denne regelen. Flere hovedkurser skal ikke ha felles nøytralleder."},
  "n52-18": {"90 °C":"90 °C er grensen for PEX og EPR, ikke PVC. PVC tåler mindre.","105 °C":"105 °C er for høyt for PVC i normal drift. Isolasjonen er ikke laget for så varme ledere.","50 °C":"50 °C er lavere enn det PVC tåler. Grensen for PVC i normal drift er høyere."},
  "n6-1": {"Ett år etter at den er tatt i bruk, og deretter hvert femte år":"Ett år etter bruk er for sent. Førstegangskontrollen skal gjøres før anlegget tas i bruk.","Hvis kunden ber om det, eller hvis forsikringsselskapet krever det":"Kundens ønske eller forsikringskrav er ikke grunnen til kontrollen. Den skal gjøres før bruk, og etter endring.","Ved salg av boligen, og da etter avtale mellom kjøper og selger":"Salg av boligen er ikke tidspunktet. Kontrollen gjelder anlegget før bruk, ikke avtale ved salg."},
  "n6-2": {"Isolasjonsmåling av kablene, og at resultatene ikke skrives ned":"Resultatene må skrives ned, ikke utelates. Måling er en del av kontrollen, men uten dokumentasjon er den ikke komplett.","En samtale med kunden om hva anlegget brukes til og hva det koster":"En samtale om pris og bruk er ikke en del av kontrollen. Den består av synlig kontroll, prøving og dokumentasjon.","Funksjonstest av lys og stikkontakter, uten visuell kontroll og måling":"Funksjonstest alene er ikke nok. Den visuelle kontrollen og målingene må også med."},
  "n6-3": {"Fordi det er lettere å se i mørket, og fordi mørke gjør det enklere å finne feil i kablene":"Det har ingenting med mørke å gjøre. Det er ikke lysforholdene som avgjør rekkefølgen.","Fordi instrumentene må varmes opp, slik at målingene blir riktige og nøyaktige":"Oppvarming av instrumenter har ingenting med den visuelle kontrollen å gjøre. Synlige feil skal finnes først.","Det spiller ingen rolle når den gjøres, fordi alle feil uansett blir oppdaget ved måling senere":"Rekkefølgen spiller rolle. Mange synlige feil finnes uten måling, og de bør rettes før anlegget får spenning."},
  "n6-4": {"500 V DC og minst 1,0 MΩ":"Dette gjelder vanlige kretser opptil 500 V, ikke SELV og PELV. Disse har lavere prøvespenning.","1000 V DC og minst 1,0 MΩ":"1000 V er for høy prøvespenning for SELV og PELV. Den brukes ikke for denne typen krets.","50 V AC og minst 1 kΩ":"50 V AC og 1 kΩ er ikke kravet for isolasjon. For SELV og PELV måles det med likespenning og MΩ."},
  "n6-5": {"500 V DC":"500 V DC er for kretser opptil 500 V. Dette anlegget er over 500 V, så prøvespenningen må være høyere.","250 V DC":"250 V DC er for SELV og PELV. Et 690 V-anlegg må måles med en mye høyere spenning.","690 V AC":"690 V er spenningen i anlegget, ikke prøvespenningen. Isolasjonsmåling gjøres med likespenning."},
  "n6-6": {"Måle mellom fase og nøytral med 1000 V, også når kursen har elektronikk som tåler det":"Målingen skal gjøres mot PE, ikke bare mellom fase og nøytral. Elektronikk kan ta skade av prøvespenningen.","Sette kursen under spenning først, og så måle mellom fase og PE med 1000 V":"Kursen skal være spenningsløs under måling. Å måle under spenning er farlig og gir feil resultat.","Fjerne PE-lederen før målingen, så utstyret ikke tar skade av testspenningen":"PE skal ikke fjernes for å beskytte utstyret. Utstyret kobles fra, eller målingen gjøres mot PE."},
  "n6-7": {"At batteriene står riktig vei, med plusspolen mot den røde kabelen":"Batterier er ikke med i kontrollen. Polaritet her gjelder bryter og sikring i fasen i en installasjon.","At motoren roterer riktig vei, og at fasene er merket L1, L2 og L3":"Rotasjonsretning på motor er fasefølge, ikke polaritet. Polaritet gjelder om brytere og vern sitter i fasen.","At jordfeilvernet er type A, og at det er koblet til hver kurs i tavla":"Type jordfeilvern og kobling til kurser sjekkes ikke med polaritet. Her gjelder det om brytere og vern står i fasen."},
  "n6-8": {"Den skal ikke kontrolleres, siden vernet er produsert etter gjeldende standard":"Et nytt vern må likevel kontrolleres ved førstegangskontroll. Produksjonsstandard er ikke en kontroll av anlegget.","Ved å se på merkingen på selve vernet og anta at det virker":"Merkingen på vernet viser ikke at det virker i dag. Det må testes, ikke antas.","Ved å lage en ekte jordfeil med en ledning til PE og måle tiden til utløsning":"En ekte jordfeil skal ikke lages med ledning til PE. Vernet testes med testknappen."},
  "n6-9": {"600 ms":"600 ms er for treigt for et vanlig jordfeilvern ved IΔn. Det skal løse ut raskere.","500 ms":"500 ms er også for lang tid for et vanlig jordfeilvern. Det skal løse ut raskere ved IΔn.","1000 ms":"1000 ms er tiden for et tidsforsinket vern. Et vanlig jordfeilvern skal være raskere."},
  "n6-10": {"Nei. Ik må være over 1 000 A for at vernet skal løse ut momentant på 16 A":"Kravet er ikke 1 000 A. For B16 holder det at feilstrømmen er over 80 A, altså 5 ganger merkestrømmen.","Nei. Zs må være under 0,1 Ω, fordi B16 bare løser ut momentant over 500 A":"B16 løser ut momentant ved ca. 80 A, ikke 500 A. Her er feilstrømmen ca. 288 A, og det er nok.","Det kan ikke avgjøres uten isolasjonsmåling og måling av jordelektrodens resistans på anlegget":"Zs-verdien og 230 V gir feilstrømmen direkte. Isolasjonsmåling er en egen prøve og trengs ikke for denne sjekken."},
  "n6-11": {"For å måle isolasjonen mellom faser før motorer kobles til":"Fasefølge måles ikke for isolasjon. Den viser rekkefølgen på fasene, og den gjelder rotasjon.","For å spare energi, siden motorer da bruker mindre strøm":"Fasefølge handler ikke om energi. Feil rekkefølge gir feil rotasjon, ikke lavere strømforbruk.","For å kontrollere jordfeilbryteren før den settes i drift":"Fasefølge er ikke en test av jordfeilbryter. Det er rekkefølgen på fasene som kontrolleres."},
  "n6-12": {"Det noteres i rapporten, og anlegget tas i bruk etter at feilen er meldt til kunden":"Å skrive feilen i rapporten er ikke nok. Feilen må rettes før anlegget tas i bruk.","Kunden avgjør om det skal rettes, og prøvingen gjentas bare hvis kunden ber om det":"Kunden avgjør ikke om feilen skal rettes. Prøvingen må gjentas selv om kunden ikke ber om det.","Ingenting, hvis jordfeilvernet virker og alle andre målinger er godkjent, og prøvingen trenger ikke gjentas":"Et godkjent vern alene er ikke nok. En feil kan ha påvirket andre målinger, og da må de gjentas."},
  "n6-13": {"At spenningen er riktig mellom fase og nøytral, og at den er stabil":"Spenning mellom fase og nøytral måles ikke her. Kontinuitetsmåling sjekker om PE er hel og har lav motstand.","At isolasjonen er god nok, og at den tåler minst 500 V DC mellom leder og jord":"Isolasjonsmåling er en egen prøve med likespenning. Kontinuitet sjekker om PE er hel, ikke isolasjonen.","At det ikke er harmoniske strømmer i kursen, og at THD-verdien er under 8 %":"Harmoniske strømmer og THD hører ikke til denne prøven. Kontinuitet sjekker om PE er sammenhengende."},
  "n6-14": {"Spenningsfall i hovedkursen":"Spenningsfall er en av de siste prøvene. Den kommer etter at de andre sjekkene er gjort.","Jordfeilvern-test av alle kurser":"Jordfeilvern-testen kommer etter at PE og polaritet er sjekket. Den er ikke den første prøven.","Funksjonsprøving av lys og kurser":"Funksjonsprøving kommer senere, etter at forbindelsene og lederne er kontrollert. Den er ikke først."},
  "n6-15": {"Med 1000 V DC, og kravet er da minst 0,5 MΩ":"1000 V er for høyt for elektronikk i kursen. 0,5 MΩ er kravet for SELV og PELV, ikke her.","Det kan ikke måles i det hele tatt på 230 V":"Det kan måles. Når vernet ikke kan kobles fra, senkes prøvespenningen for kursen.","Med 500 V DC, med vernet koblet inn":"500 V med vernet inne er for høyt for elektronikken. Der vernet ikke kan kobles fra, må spenningen senkes."},
  "n6-16": {"Bare hvilken dato anlegget ble levert og hvem som har montert det, pluss navnet på kunden":"Dato og navn er ikke det viktige. Kursfortegnelsen må vise tekniske data for hver kurs.","Prisen på materiellet og hva kunden skal betale for kursen, samt dato for når kursen ble lagt":"Pris hører ikke hjemme i kursfortegnelsen. Den skal vise hva kursen forsyner og hvilke vern som er brukt.","Navnet på montøren og telefonnummeret til den som utførte arbeidet, samt garantitiden":"Kontaktinfo og garanti er ikke med. Kursfortegnelsen viser de tekniske dataene for hver kurs."},
  "n6-17": {"Høyst 10 % fra leveringspunktet til utstyret":"10 % er for høyt når utstyrets grense er ukjent. Den anbefalte grensen er lavere.","Høyst 1 % fra leveringspunktet til utstyret":"1 % er strengere enn anbefalingen, og det er ikke det som kreves.","Ingen anbefaling for spenningsfall i normen":"Det finnes en anbefaling i normen. Den gjelder når utstyrets grense er ukjent."},
  "n6-18": {"Den skal kobles til beskyttelseslederen under hele målingen":"Da måler man ikke N mot PE. Forbindelse mellom N og PE gjør at målingen ikke gir mening.","Den skal fjernes fra kursen under hele isolasjonsmålingen":"Å fjerne N fra kursen er ikke kravet. Det viktige er at N ikke er koblet til PE under målingen.","Den skal kobles til en fase under hele isolasjonsmålingen":"Å koble N til en fase er heller ikke kravet. Det som gjelder er at N og PE ikke er forbundet."},
  "n6-19": {"Det høyeste måleresultatet (beste)":"Det høyeste tallet viser bare det beste punktet. Det skjuler svake punkter i anlegget.","Gjennomsnittet av målingene i anlegget":"Et gjennomsnitt skjuler dårlige punkter. Dokumentasjonen skal vise det svakeste resultatet.","Det første måleresultatet som ble tatt":"Det første tallet sier lite om hele anlegget. Det er ikke det som skal dokumenteres."},
  "e8": {"Fordi Z er over 1 Ω, og da er feilstrømmen liten nok":"Høy Z gir ikke automatisk godkjent. Her er Ik målt til 174 A, og det er den verdien som sammenlignes.","Fordi 174 A er under grensen for C16 på 16 · 16 A":"16 · 16 A er ikke grensen. Grensen for C er 10 ganger merkestrømmen, og 174 A er over den.","Fordi målingen er gjort i et IT-system, der alt er godkjent":"Et IT-system gjør ikke målingen godkjent av seg selv. Godkjenning avhenger av Ik mot grensen."},
  "e9": {"Nei, den skal løse ut ved nøyaktig 30 mA, og bare da, fordi alt under 30 mA er en feil i vernet":"Vernet må ikke løse ut nøyaktig ved 30 mA. Det er lov å løse ut under merkeverdien, ned til halvparten.","Nei, den løste ut for sent, fordi tidsgrensen for 30 mA-vern er 1 sekund":"Tidsgrensen er ikke 1 sekund for et vanlig 30 mA-vern. Den er mye kortere, og 13 ms er godt innenfor.","Nei, den skal ikke løse ut under 50 mA, fordi vernet er laget for høyere strøm":"Vernet skal ikke vente til 50 mA. Det skal løse ut ved eller under 30 mA, og det gjorde det her."},
  "e10": {"Testtypen kan stå på AC, siden type AC-vern er vanlig i tavla, også vern med elektronikk":"Type AC passer ikke til vern med elektronikk. Elektronikk kan gi pulserende likestrøm, som type AC ikke ser.","Type AC betyr at testen gjøres med likestrøm, så instrumentet må settes til DC-test for kursene i tavla, også vern med elektronikk":"Type AC betyr ikke likestrøm-test. Det betyr at vernet bare er laget for feil med vekselstrøm.","Type AC betyr at det er et trefaset vern som må testes med 400 V mellom fasene i anlegget":"Type AC handler om hvilken feilstrøm vernet ser, ikke om antall faser eller spenning mellom fasene."},
  "e11": {"Minst 999 MΩ":"999 MΩ er bare det målte tallet. Det er ikke kravet, som er et lavere minstetall.","Minst 0,5 MΩ ved 250 V":"250 V og 0,5 MΩ gjelder SELV og PELV. Denne 230 V-kursen måles med 500 V.","Under 1 Ω":"Ohm-grensen gjelder kontinuitet i PE, ikke isolasjon. Isolasjon måles i megaohm, og da med 500 V."},
  "e12": {"Bare at lokket lukker seg og at kontakten er tett":"Lokk og tetthet er bra å sjekke, men det er ikke kontrollen her. Fasefølgen er det som avgjør motorens retning.","At kontakten har 30 mA type AC jordfeilvern, og at den er koblet riktig":"Et jordfeilvern på kontakten er ikke fasefølgen. Kontrollen her gjelder rekkefølgen på fasene.","At den er koblet til 230 V enfase, med nøytral og PE samlet i én leder":"En 3-fase CEE-kontakt er ikke en 230 V enfase-kurs. Den er laget for tre faser, og fasene må kontrolleres."},
  "n701-1": {"1,20 m":"1,20 m gjelder vannrett avstand ved dusjen, ikke høyden på sonen.","2,50 m":"2,50 m er høyere enn sone 1 går. Sonen går til 225 cm, eller høyere hvis dusjhodet sitter høyere.","3,00 m":"3,00 m er langt over sone 1. Sonen går til 225 cm, med mindre dusjhodet sitter høyere."},
  "n701-2": {"1,2 m":"1,2 m er radiusen rundt dusjen. Ved badekaret er sone 2 et smalere område, 60 cm.","0,3 m":"30 cm er for smalt. Sone 2 ved badekar er 60 cm utenfor sone 1.","2,25 m":"2,25 m er høyden for sone 1, ikke bredden på sone 2."},
  "n701-3": {"IPX7":"IPX7 gjelder nedsenking, og er kravet i sone 0. Sone 1 og 2 har et lavere minstekrav.","IPX0":"IPX0 betyr ingen beskyttelse mot vann. Det er ikke nok i et baderom.","IPX1":"IPX1 tåler bare drypp rett ned. Sprut fra alle retninger krever mer."},
  "n701-4": {"IPX4":"IPX4 tåler sprut, men ikke nedsenking. Sone 0 krever at utstyret tåler å stå i vann.","IPX2":"IPX2 tåler bare drypp i en vinkel. Det er for lite i sone 0, der utstyret kan stå i vann.","IP20":"IP20 gir ingen beskyttelse mot vann. Det kan ikke brukes i sone 0."},
  "n701-5": {"Alt utstyr med jordfeilvern og IPX4, også med vanlig 230 V-forsyning fra kursen":"Jordfeilvern og IPX4 er ikke nok i sone 0. Vanlig 230 V-utstyr er ikke tillatt der.","Stikkontakter med lokk og IP44, plassert i sone 0 bak badekaret":"Stikkontakter er ikke tillatt i sone 0, selv med lokk og IP44.","Utstyr på 50 V AC med IPX4, og fast tilkoblede apparater med vanlig 230 V-forsyning":"50 V AC er for høyt i sone 0. Der er bare svært lav spenning trygt, og 230 V er ikke tillatt."},
  "n701-6": {"Bare stikkontaktene i rommet, og bare de som ligger nærmest vasken og dusjen, uten lysarmaturer":"Lys og annet utstyr er ikke unntatt. Alle kurser i rommet skal ha vern, ikke bare stikkontaktene.","Bare varmekablene i gulvet, siden de er de eneste kursene som har høy belastning":"Varmekablene er ikke de eneste som gjelder. Også lys, stikkontakter og andre kurser i rommet er med.","Ingen, hvis det er IT-system, eller hvis kursen har en automat på 16 A":"Et IT-system eller en 16 A-automat fritar ikke fra kravet. Kursene i rommet skal ha 30 mA-vern."},
  "n701-7": {"0,6 m":"60 cm er for kort. Sonen går ut til en sylinder med radius 120 cm fra vannuttaket.","2,25 m":"2,25 m er høyden for sone 1, ikke avstanden ut fra vannuttaket.","3 m":"3 m er langt mer enn det sonen går ut i en dusj uten kar. Radiusen er 120 cm."},
  "n701-8": {"Ingenting, siden kabelen er skjermet fra fabrikken og ikke trenger noe ekstra metall over seg":"Kabelen mangler jordet skjerm, så den trenger metallnett. Å ikke legge noe er derfor feil.","Kabelen skal kobles til 400 V mellom to faser, og den skal ligge i en egen krets":"Å koble til 400 V mellom faser gir ikke skjerming. Problemet løses med metallnett koblet til PE.","Kabelen må ligge i plastrør med en diameter på minst 30 mm, slik at den ikke tar skade":"Plastrør gir ikke jording. Kravet er et metallnett over kabelen, koblet til PE."},
  "n701-9": {"Ja, med 30 mA jordfeilvern og lokk på stikkontakten i sone 1":"Jordfeilvern og lokk gjør ikke en vanlig 230 V-kontakt lovlig i sone 1. Her må det være SELV eller PELV.","Ja, hvis den er IPX4 eller høyere og har jordfeilvern":"IPX4 og jordfeilvern er ikke nok. Sone 1 har egne krav til spenningen, og en vanlig 230 V-kontakt er ikke tillatt.","Ja, hvis den har lokk og er montert minst 2,25 m over gulv, i sone 1 og 2":"Lokk og høy montering er ikke nok. Stikkontakten i sone 1 må være for lav spenning, som SELV eller PELV."},
  "n701-10": {"Fordi baderom er små, og det derfor er vanskelig å holde god avstand til jordede deler":"Små rom er ikke grunnen. Det er at kroppen har lav motstand når den er våt, som gjør strømmen farligere.","Fordi det er mer utstyr på bad, som varmtvannsbereder, vaskemaskin og elektrisk gulvvarme":"Mer utstyr er ikke hovedgrunnen. Kravene er strengere fordi den våte kroppen blir mer utsatt for strøm.","Fordi baderom har høyere nettspenning på stikkontaktene enn resten av boligen":"Nettspenningen er den samme i hele boligen. Det er kroppens motstand som gjør baderommet farligere."},
  "n701-11": {"IPX4":"IPX4 holder til vanlig bruk, ikke til vannstråle. Da trengs høyere beskyttelse ved spyling.","IPX2":"IPX2 tåler bare drypp. Det er for lite der det spyles med vann.","IPX0":"IPX0 har ingen vannbeskyttelse i det hele tatt. Det kan ikke brukes der det spyles."},
  "n701-12": {"Speilet over vasken og lampen i taket":"Speil og lampe er ikke med i tilleggsutjevningen. Det er sluket eller avløpet som skal med.","En treskammel som ikke leder strøm":"Et treskammel leder ikke strøm, så det hjelper ikke i utjevningen. Det er ikke det som skal kobles.","Ingenting, selv om badet har gulvvarme":"Gulvvarme gjør utjevningen mer aktuell, ikke unødvendig. Sluket skal være med i tilleggsutjevningen."},
  "n701-13": {"Minst 1 cm fra veggoverflaten":"1 cm er for nær overflaten. Da er det lett å treffe kabelen når man borer.","Maks 3 cm fra veggoverflaten":"3 cm er ikke et maksimum. Kabelen skal ligge dypere enn det, for å bli beskyttet mot boring.","Det er ingen krav til dybde":"Det er krav til dybde. Dypt nok fra overflaten gjør at man ikke borer i kabelen ved montering."},
  "n701-14": {"Kravene for sone 2, som er mindre streng":"Sone 2 er mindre streng. Lampen må oppfylle det strengeste kravet, som gjelder sone 1.","Ingen krav, fordi lampen er i to soner":"At lampen står i to soner gir ikke færre krav. Begge soner gjelder, og da gjelder den strengeste.","Gjennomsnittet av kravene i sonene":"Det finnes ikke gjennomsnitt av krav. Utstyr må oppfylle den strengeste sonen."},
  "n722-1": {"Fra en vanlig stikkontaktkurs sammen med annet utstyr":"Et ladepunkt skal ikke deles med annet utstyr. Det trekker mye strøm over lang tid.","Fra lyskursen, så lenge den har 30 mA jordfeilvern":"Lyskursen er ikke egnet, selv med jordfeilvern. Ladepunktet trenger sin egen kurs og sitt eget vern.","Fra en felles kurs for alle ladepunkter i garasjen":"Ladepunkter skal ikke dele en felles kurs. Hvert ladepunkt skal ha sin egen kurs og sitt eget vern."},
  "n722-2": {"300 mA type AC felles for ladepunktene i samme anlegg, også i garasjen":"300 mA er for høyt, og vernet skal ikke være felles for flere ladepunkter. Det skal ikke beskytte andre.","Det kreves ikke, siden laderen har eget vern for både overlast og kortslutning":"Overlastvern og kortslutningsvern i laderen erstatter ikke jordfeilvern. Det skal fortsatt være et eget vern.","Automatsikring på kursen, med B16 og lekkasjevern type AC på 30 mA i tavla for laderen":"Type AC ser ikke DC-feilstrøm. Ladepunktet trenger type B, eller type A eller F med DC-deteksjon."},
  "n722-3": {"Den løser ut for ofte på grunn av ladestrømmen, og det gjør den upraktisk":"Den løser ikke ut for ofte. Problemet er at den ikke registrerer DC-feilstrømmer, og da kobler den ikke ut når det trengs.","Den er for dyr i forhold til vanlige jordfeilbrytere, og den finnes i store anlegg":"Pris og størrelse er ikke problemet her. Type AC registrerer bare vekselstrøm, og DC-feil kan gjøre at den ikke kobler ut.","Den virker bare i IT-system, og den må derfor kombineres med en jordelektrode":"Dette er ikke grunnen. En jordelektrode endrer ikke at type AC ikke ser DC-feilstrømmer, og det kan svekke utkoblingen."},
  "n722-4": {"Ja, hvis kabelen har over 10 mm² tverrsnitt":"Tverrsnittet endrer ikke saken. Kursen til ladepunktet i TN-system skal ikke ha PEN-leder, og brudd på PEN kan gi farlig spenning på bilen.","Ja, siden PEN-lederen er trygg nok i fast anlegg":"Fast anlegg gjør ikke PEN-lederen trygg. Brudd på PEN kan gi farlig spenning på bilens karosseri.","Ja, med PEN i sluttkursen ved 3-fase lading":"Trefase lading endrer ikke kravet. Ved brudd på PEN kan bilens karosseri få farlig spenning, og kursen skal ikke ha PEN-leder."},
  "n722-5": {"0,5, altså at halvparten av ladepunktene lader samtidig, uten laststyring":"Halvparten er ikke nok uten laststyring. Hvert ladepunkt regnes med sin merkestrøm, og samtidighetsfaktoren settes til full verdi.","0,2, altså at bare hvert femte ladepunkt regnes med full last":"Bare hvert femte er for lavt. Ladepunkter regnes som belastet med sin merkestrøm, med mindre det finnes laststyring.","0, fordi bilene lader om natten, og da er det ingen last på anlegget":"Null last er feil. Ladepunkter regnes som belastet med sin merkestrøm, uansett når bilene lader."},
  "n722-6": {"Lading fra vanlig stikkontakt med kontrollboks på kabelen":"Dette beskriver lademodus 2, som bruker vanlig stikkontakt og en boks på kabelen, ikke en fast stasjon.","DC-hurtiglading med høy effekt der styring og kommunikasjon ligger i kabelen":"Høy effekt med DC-hurtiglading er lademodus 4, der stasjonen leverer likestrøm. Det er ikke lademodus 3.","Lading uten noen form for kontroll, direkte fra en 400 V-kurs uten jordfeilvern":"Lading direkte fra en kurs uten kontroll er ikke lademodus 3. Lademodus 3 er vanlig hjemmelader, en fast ladestasjon med styring."},
  "n722-7": {"DC-hurtiglading ved veien, med kabel som er fast montert på stolpen":"DC-hurtiglading er lademodus 4, med likestrøm fra stasjonen. Lademodus 2 bruker vanlig stikkontakt og en boks på ladekabelen.","Fast ladestasjon på veggen med Type 2-kontakt, egen kurs i tavla":"Dette beskriver lademodus 3, en fast ladestasjon på veggen. Lademodus 2 bruker vanlig stikkontakt, ikke en fast stasjon.","Trådløs lading i gulvet, uten kabel og uten noen kontrollboks eller vernboks":"Her finnes ingen kabel og ingen boks, så dette er ikke lademodus 2. Lademodus 2 har en boks på ladekabelen som gir vern."},
  "n722-8": {"Lading fra 230 V stikkontakt i garasjen, der bilen styrer strømmen selv":"Lading fra vanlig stikkontakt er ikke lademodus 4. Lademodus 4 gir likestrøm direkte fra stasjonen, ikke fra stikkontakten.","Lading med 3-fase vekselstrøm i garasjen, der likeretteren står i bilen":"Vekselstrøm og likeretter i bilen passer ikke med lademodus 4. Der leverer stasjonen likestrøm til batteriet.","Lading fra solcellepanel direkte til batteriet, uten ladestasjon":"Solcelle direkte til batteriet er ikke lademodus 4. Her mangler ladestasjonen, som skal levere likestrømmen."},
  "n722-9": {"Ca. 3,7 kW":"3,7 kW er 230 V ganget med 16 A, altså 1-fase. Her er det trefase med 400 V, og da gir 16 A mer effekt.","Ca. 6,4 kW":"6,4 kW er 400 V ganget med 16 A, uten √3. For trefase må man gange med √3 i tillegg.","Ca. 22 kW":"22 kW gjelder 32 A, ikke 16 A. Ved 16 A blir effekten bare omtrent halvparten."},
  "n722-10": {"Ca. 3,7 kW":"3,7 kW er for 230 V og 16 A. Her er strømmen 32 A, så effekten blir dobbelt så stor.","Ca. 11 kW":"11 kW er trefase med 400 V og 16 A. Ved 230 V og 32 A i én fase blir effekten lavere enn dette.","Ca. 22 kW":"22 kW er trefase med 32 A. Med 230 V og én fase blir effekten mye lavere enn 22 kW."},
  "n722-11": {"IPX0 mot vann og IP2X mot fremmedlegemer":"IPX0 gir ingen vern mot vann, og IP2X gir for lite vern mot fremmedlegemer utendørs. Utendørs kreves et høyere nivå.","IPX2 mot vann og IP20 mot fremmedlegemer":"IPX2 og IP20 er for lave utendørs. Regn og sprut krever bedre vern mot vann, og vernet mot fremmedlegemer må være høyere.","IP2X mot vann og IPX4 mot støv og sand":"Vann og støv er blandet om. Tallet rett etter IP gjelder fremmedlegemer og støv, og tallet etter X gjelder vann."},
  "n722-12": {"Det er ikke tillatt å ha overspenningsvern i installasjonen":"Overspenningsvern i installasjonen er ikke forbudt. Det skal beskytte ladepunktet, fordi bilen og laderen har mye følsom elektronikk.","Overspenningsvern kreves bare for ladepunkter med DC-lading i installasjonen":"Kravet gjelder ladepunkter generelt, ikke bare DC. Overspenning kan skade følsom elektronikk i bil og lader.","Ladepunkter over 22 kW skal ha eget overspenningsvern inne i selve laderen":"Grensen på 22 kW finnes ikke her. Kravet gjelder alle ladepunkter, og vernet skal være i installasjonen."},
  "n722-13": {"Vanlig jordet stikkontakt, som er godkjent for lading av elbil":"En vanlig stikkontakt er ikke godkjent som tilkoblingspunkt for elbil. Her kreves en Type 2-løsning, ikke en stikkontakt.","CEE-kontakt 63 A, som er standard for lading av alle elbiler":"CEE 63 A er ikke standard for alle elbiler. For AC-tilkobling av bil brukes Type 2, ikke CEE.","Hva som helst som passer i bilens ladeport og er merket for 230 V":"Merking for 230 V gjør ikke en kontakt riktig for elbil. Tilkoblingspunktet må være Type 2, og passende form er ikke nok."},
  "n722-14": {"Ja, hvis den er 2,5 mm²":"Tverrsnittet endrer ikke saken. En skjøteledning er flyttbar, og flyttbare kontakter er ikke tillatt ved tilkoblingspunktet.","Ja, hvis den er under 10 m":"Lengden spiller ingen rolle. Skjøteledningen er flyttbar, og et tilkoblingspunkt for elbil skal ikke ha slike forbindelser.","Ja, utendørs":"Utendørs gjør det ikke bedre. Et tilkoblingspunkt skal bare forsyne ett kjøretøy, og flyttbare elbilkontakter er ikke tillatt."},
  "n722-15": {"Ikke noe ekstra utstyr":"Dette er feil. Når første jordfeil ikke kobles ut, må den oppdages på en annen måte, og det krever utstyr.","Et vanlig overstrømsvern":"Overstrømsvern reagerer ikke på en første jordfeil. Kursen trenger utstyr som varsler ved jordfeil.","Et termisk motorvern på kursen":"Motorvern er ikke svaret her. Feilen kobles ikke ut av seg selv, så kursen skal ha utstyr som varsler om jordfeil."},
  "n7-1": {"Med automatsikring på hver kurs, eller med vanlig kabel og vanlig stikkontakt uten ekstra vern":"Automatsikring beskytter mot overlast, ikke mot støt. Byggeplassen krever ekstra personvern, og vanlig stikkontakt uten vern er for farlig.","Med 300 mA jordfeilvern på hele byggeplassen, eller med ekstra jording av stikkontaktene i stedet for vern per kurs i anlegget":"300 mA er brannvern, ikke personvern. Ekstra jording erstatter ikke vernet, og byggeplassen må ha ekstra personvern.","Det er ikke spesielle krav, så lenge stikkontaktene er merket og kursen har vanlig overstrømsvern og vanlig jording i byggeplassen":"Det finnes spesielle krav på byggeplass. Vanlig overstrømsvern og jording gir ikke nok personvern mot støt."},
  "n7-2": {"Høyst 3 A":"3 A er langt over grensen. Brannvernet må løse ut ved mye lavere feilstrøm enn dette.","Høyst 1 A":"1 A er også for høyt. Brannvernet må løse ut før feilstrømmen kan starte brann, og den grensen er 300 mA.","Det kreves ikke jordfeilvern":"Jordfeilvern kreves her, fordi en feilstrøm kan starte brann. Det er et krav, ikke et valg."},
  "n7-3": {"Høyst 3 A, eller høyst 1 A der feilen kan oppstå i en resistiv last som et varmeelement i kjøkkenet":"3 A er for høyt, selv om feilen er i et varmeelement. Vernet må løse ut før feilstrømmen kan starte brann.","Høyst 1 A for anlegget, også der feilen kan oppstå i en resistiv last som et varmeelement":"1 A er for høyt, og det gjelder også der feilen kan skje i et varmeelement. Vernet må være mye lavere.","Det brukes ikke jordfeilvern mot brann, siden vernet beskytter mot støt":"Jordfeilvern brukes også mot brann, ikke bare mot støt. En jordfeilstrøm på noen hundre milliampere kan starte brann."},
  "n7-4": {"Stikkontakter, så lenge de er jordet":"Jording alene er ikke nok i sone 1. Her skal det bare være utstyr som hører til badstuovnen, og stikkontakter hører ikke dit.","Vanlige lysbrytere og lysarmaturer":"Lysbrytere og armaturer hører ikke til ovnen, og sone 1 er ikke et sted for vanlig utstyr.","Alt som er IPX4 og tåler 60 °C i sone 1":"IPX4 og 60 °C gjør ikke utstyr tillatt i sone 1. Alt i badstuen skal minst være IP24, men det avgjør ikke hva som kan stå her."},
  "n7-5": {"Hver stikkontakt skal ha eget overstrømsvern, og kurser inntil 63 A skal ha 300 mA jordfeilvern":"300 mA er brannvern, ikke personvern. Kurser inntil 63 A skal ha 30 mA for å beskytte personer mot støt.","Flere stikkontakter kan dele ett overstrømsvern, og kurser inntil 63 A skal ha 30 mA jordfeilvern":"Deling av vern er ikke lov her. Hver stikkontakt skal ha sitt eget vern, så én feil ikke slår ut de andre.","Hver søyle skal ha ett felles overstrømsvern, og kurser inntil 63 A skal ha 30 mA jordfeilvern":"Ett felles vern per søyle er feil. Hver stikkontakt skal ha eget overstrømsvern, så én feil ikke slår ut de andre."},
  "n7-6": {"Vanlig 230 V lampe med jordfeilvern, og tanken kobles til jord":"230 V er for farlig i en trang metalltank. Jordfeilvern og jording av tanken er ikke nok, fordi du står i kontakt med jordet metall.","230 V lampe i klasse I med god jording, med strømkilden inne i tanken":"Jording og klasse I er ikke nok her. Strømkilden kan ikke stå inne i tanken, og 230 V er for høy spenning.","400 V lampe med 30 mA jordfeilvern og strømkilden inne i tanken, uten å bruke SELV":"400 V er svært farlig i en trang tank. Bare SELV, eller elektrisk adskillelse til ett apparat, er trygt når du står i metall."},
  "n7-7": {"230 V med jordfeilvern på 30 mA, og med strømkilden plassert nær vannkanten":"230 V er langt over grensen i sone 0 og 1. Jordfeilvern og strømkilde nær vannet endrer ikke at spenningen er for høy.","50 V AC, med strømkilden utenfor sone 0 og 1, og med vanlig jordfeilvern på 30 mA":"50 V AC er for høyt i sone 0 og 1, der bare svært lav spenning er lov. Jordfeilvern endrer ikke dette.","400 V, med strømkilden utenfor sone 0 og 1, og med vanlig jordfeilvern type B":"400 V er langt for høyt når man er i vannet. Type B-vern endrer ikke at bare svært lav spenning er lov."},
  "n7-8": {"Det er bare anbefalt i næringsbygg og større bolighus, men ikke krevd i noen type installasjon":"Dette er ikke bare en anbefaling. Kravet gjelder alle installasjoner utenfor distribusjonsnettet.","Det kreves bare i hus med lynavleder, og bare der distribusjonsnettet er luftledning":"Lynavleder og luftledning er ikke vilkårene. Det avgjørende er om installasjonen er utenfor distribusjonsnettet.","Overspenningsvern er ikke tillatt i lavspenningsanlegg, bare i distribusjonsnettet":"Dette er motsatt. Overspenningsvern er ikke forbudt i lavspenningsanlegg, og kravet gjelder installasjoner utenfor distribusjonsnettet."},
  "n7-9": {"Flere båter kan dele én stikkontakt med eget overstrømsvern, og stikkontakter inntil 63 A skal ha 30 mA jordfeilvern":"Hver stikkontakt skal bare forsyne én båt, selv med eget vern. Flere båter på én stikkontakt er ikke lov.","Hver søyle kan ha én felles sikring på 32 A, og stikkontakter inntil 63 A skal ha 30 mA jordfeilvern":"Felles sikring per søyle er feil. Hver stikkontakt skal ha eget vern og bare forsyne én båt.","Hver stikkontakt skal ha eget overstrømsvern, og stikkontakter inntil 63 A skal ha 300 mA jordfeilvern":"300 mA er for høyt for personvern. Stikkontakter inntil 63 A skal ha 30 mA for å beskytte personer mot støt."},
  "n7-10": {"25 m":"25 m er for langt. Kravet skal hindre lange skjøteledninger, så avstanden må være kortere enn dette.","50 m":"50 m er mye for langt. Lange skjøteledninger er det kravet skal hindre, og avstanden må være kort.","2 m":"2 m er ikke grensen. Kravet er en øvre grense, og den er høyere enn to meter."},
  "n7-11": {"Kursen til badstuovnen, og ingen andre kurser i rommet":"Dette er motsatt. Kursen til ovnen er unntatt, og alle andre kurser i rommet skal ha jordfeilvern.","Ingen, fordi alle kurser i rommet har eget vern":"Eget overstrømsvern er ikke det samme som jordfeilvern. Kursene i rommet skal ha 30 mA jordfeilvern.","Alle kurser unntatt lyset, også kursen til badstuovnen":"Her er unntaket satt på feil kurs. Lyskursen skal ha jordfeilvern, mens kursen til ovnen er unntatt."},
  "n7-12": {"De skal være tidsforsinket type S, og kan ved behov være inntil 300 mA hvis lekkstrømmen gir utkoblingsproblemer":"Tidsforsinket vern er feil for varmekabler. Kravet er et vern uten forsinkelse, og 300 mA er for høyt.","Varmekabler trenger ikke jordfeilvern, siden lekkasjestrømmen er så liten at den ikke kan gi farlig støt":"Liten lekkasje er ikke et trygt grunnlag. Varmekabler skal ha jordfeilvern for å beskytte mot støt.","De skal være tidsforsinket 1 s, og varmekablene kan samles på én kurs med 30 mA vern":"Forsinket utkobling er feil her. Kursene skal deles opp, så normal lekkasje ikke gir uønsket utkobling."},
  "n823-1": {"Stikkontaktkursene":"Stikkontaktkursene er bare en del av det. Kravet gjelder hver forbrukerkurs, også andre kurser i boligen.","Kurser over 16 A":"Størrelsen på kursen er ikke grensen. Alle forbrukerkurser skal ha 30 mA, uansett hvor stor sikringen er.","Kurser til vaskerom":"Vaskerom er bare ett eksempel. Alle forbrukerkurser i boligen skal ha 30 mA, ikke bare de på vaskerommet."},
  "n823-2": {"IB ≤ In ≤ Iz og I2 ≤ 1,45 · Iz":"1,45 ganger Iz er den generelle regelen, og den gjelder ikke i bolig for små ledere. Vernet må løse ut før strømmen går over Iz.","In ≤ 2 · Iz":"Faktor 2 er for høy. Vernet må løse ut sikkert før strømmen går over Iz, ikke ved to ganger.","Bare IB ≤ In":"IB ≤ In er ikke nok alene. Også I2 må være innenfor Iz for å redusere faren for brann."},
  "n823-3": {"16 A":"16 A gir I2 på omtrent 23 A med faktoren 1,45. Det er over 20 A, så vernet er for stort.","20 A":"20 A gir I2 på omtrent 29 A med faktoren 1,45. Det er langt over kursens 20 A, så vernet er altfor stort.","10 A":"10 A er trygt, men det er ikke den største. Et større standardvern under grensen kan brukes."},
  "n823-4": {"Ja, reglene for PVC-kabler gjelder også i boliger":"Reglene gjelder ikke i boliger. Det står i 8-823, så de særnorske PVC-reglene er ikke riktige her.","Ja, men ikke i rekkehus og leiligheter":"Rekkehus og leiligheter er boliger, og for boliger gjelder ikke de særnorske reglene.","Ja, de gjelder for aluminiumskabler i boliger og hytter":"Materialet endrer ikke saken. Reglene gjelder ikke i boliger, verken for aluminium eller andre kabler."},
  "n823-5": {"En egen kurs til komfyren, og en røykvarsler over komfyren i kjøkkenet":"Røykvarsler kobler ikke ut strømmen. Komfyren krever utstyr som kobler ut før overoppheting gir brannfare.","Et lite vern som kobles inn i kontakten for komfyren, slik at den kan brytes ved overlast":"Et vern i kontakten er ikke nok. Utstyret skal koble ut før overoppheting gir brannfare, og det skal være fast montert.","Et jordfeilvern på 300 mA i tavla, og en egen kurs for komfyren":"Et jordfeilvern reagerer på lekkasje, ikke på varme. Komfyren trenger et eget beskyttelsesutstyr mot overoppheting."},
  "n823-6": {"2":"To uttak er langt for få. Kravet er to uttak per påbegynt 4 m², og et 15 m² soverom får flere enn det.","4":"Fire er for få. Kravet er to uttak per påbegynt 4 m², og 15 m² gir fire slike arealer.","6":"Seks er for få. Det skal være to uttak for hver påbegynt 4 m², og det blir flere enn seks."},
  "n823-7": {"Ett per 2 m benk":"Ett uttak per 2 m er for få til kjøkkenmaskiner. Kravet er et høyere antall uttak per 2 m kjøkkenbenk.","To totalt":"Totalt to uttak er for få. Kravet gjelder per 2 m benk, så en lang benk trenger flere uttak.","Fire per meter":"Kravet er ikke per meter. Det er per 2 m kjøkkenbenk, så fire per meter er ikke riktig måte å telle på."},
  "n823-8": {"2":"To uttak er for få. Gangen skal ha minst to per påbegynt 6 m², og 10 m² gir to påbegynte arealer.","6":"Seks er mer enn minimum. Kravet er to per påbegynt 6 m², og 10 m² gir to slike arealer.","8":"Åtte er mer enn det minste kravet. Med to uttak per påbegynt 6 m² blir det bare to påbegynte arealer på 10 m²."},
  "n823-9": {"0":"Null uttak er ikke godtatt. En veranda ved boligen skal ha minst to uttak.","1":"Ett uttak er for lite. Kravet er minst to uttak, altså flere enn ett.","4":"Fire er mer enn det minimum som kreves. Kravet er minst to uttak på veranda eller terrasse ved boligen."},
  "n823-10": {"0":"Null uttak er ikke godtatt. Hovedregelen er minst to, og under 3 m² godtas bare ett.","2":"To er mer enn minimum her. Under 3 m² godtas ett uttak, så kravet er lavere enn to.","3":"Tre er mer enn kravet. Når badet er under 3 m², godtas ett uttak som minimum."},
  "n823-11": {"Minst 4, hvorav minst 2 jordet":"Fire uttak med to jordede er for få. Der flere multimedieenheter er planlagt, må det være flere uttak enn dette.","Minst 1 per enhet, alle jordet":"Ett uttak per enhet er ikke nok. Kravet gjelder et samlet antall uttak, og ikke ett per enhet.","Høyst 3, hvorav høyst 2 jordet":"Dette er et maksimum, men kravet er et minimum. Ved flere multimedieenheter må det være flere uttak, ikke færre."},
  "n823-12": {"Minst 10 %":"10 % er for lite. En ny tavle skal ha mer ledig plass, så det blir rom for flere kurser senere.","Minst 50 %":"50 % er ikke kravet. Kravet er lavere, og en ny tavle skal ha 30 % ledig plass.","Ingen krav":"Det finnes et krav. En ny fordelingstavle i bolig skal ha ledig plass, så flere kurser kan legges til senere."},
  "n823-13": {"Hvert år, og etter hver større ombygging":"Hvert år er for ofte som første kontroll. Anlegg slites og endres over tid, så det holder med en senere kontroll.","Senest etter 30 år, og ved feil":"30 år er for lenge. Første kontroll anbefales tidligere, fordi anlegget kan slites eller endres over tid.","Først når det oppstår feil eller anlegget slutter å virke":"Å vente til noe feiler er for sent. Anlegget slites og endres over tid, så det skal kontrolleres periodisk."},
  "n823-14": {"Avløpsrøret skal isoleres fra annet ledende materiale i huset, med isolerende mansjett ved hver gjennomføring og ved sluket":"Isolering er motsatt av det som kreves. Avløpsrøret skal være utjevnet, så farlig spenning ikke oppstår mellom sluk og andre ledende deler.","Avløpsrøret skal brukes som PE-leder til jordelektroden, uten egen utjevningsforbindelse i huset":"Avløpsrøret skal ha egen forbindelse i huset. Det holder ikke å bruke røret som jordleder for å spare utjevning.","Avløpsrøret kan hoppes over, siden plastrør ikke leder strøm, og jording av tavla er nok":"Plastrør må også utjevnes. Jording av tavla dekker ikke avløpsrøret, og det skal ha egen forbindelse."},
  "n823-15": {"I en vanlig stikkontakt på 16 A med 30 mA jordfeilvern, også i garasjen":"En vanlig stikkontakt kan bli overopphetet av langvarig høy last. Jordfeilvern endrer ikke dette.","Via skjøteledning med tykk kabel, koblet til en stikkontakt i gangen":"Skjøteledning er ikke en godkjent måte her. Langvarig høy last kan gi overoppheting i en vanlig kontakt.","Den kan ikke kobles til i boliger, bare i industri og på lager":"Dette er feil. En varmtvannsbereder over 1500 W kan kobles til i bolig, på faste måter eller med industristikkontakt."},
  "n823-16": {"Fakturaen og en kvittering for materialene, og en muntlig orientering om hvordan vernene fungerer":"Faktura og kvittering viser bare betalingen. Eieren skal få dokumentasjon som trengs for å bruke og kontrollere anlegget.","Et skriftlig tilbud og en garanti for arbeidet i ti år, og en oversikt over hvem som kan kontaktes ved feil":"Tilbud og garanti er ikke dokumentasjonen for anlegget. Eieren skal ha rapporter, kursfortegnelse og bruksanvisning.","Dokumentasjonen skal lagres hos installatøren i ti år, og eieren får en muntlig orientering om hvordan anlegget fungerer og hvem som kan kontaktes":"Dokumentasjonen skal ikke bare ligge hos installatøren. Eieren skal få den, og en muntlig orientering er ikke nok."},
  "n823-17": {"Det holder med at bruksanvisningen forklarer hvordan vernet fungerer og hvor det sitter, uten egen varsling":"Bruksanvisning alene er ikke nok. Når vernet ikke lenger virker, skal det gi et lyd- eller lyssignal.","At vernet byttes hvert år, enten det har løst ut eller ikke, og at varsling i boligen er frivillig":"Årlig bytte av vern er ikke kravet. Varsling er ikke frivillig, fordi man ellers ikke merker at beskyttelsen er borte.","At overspenningsvernet flyttes inn i sikringsskapet, fordi det ikke er lov å ha det i tilknytningsskapet":"Vernet kan sitte i tilknytningsskapet, så det er ingen krav om å flytte det. Kravet er signal når vernet ikke virker."},
  "n823-18": {"De skal ha IP68, og de kan sitte under 0,3 m over gulvet når de er montert i fuktige rom på badet":"IP68 hjelper ikke mot fare for barn. Stikkontakten må ha barnesikring, sitte høyt eller være utilgjengelig for barn.","De skal sitte under 0,3 m over gulvet, slik at de er enkle å nå for både barn og voksne":"Under 0,3 m er nær barnas hender, og det er motsatt av kravet. Stikkontakten må være høy eller ha barnesikring.","Det holder med jord og merking, så lenge de er montert i veggen og lett synlige":"Jord og merking beskytter ikke barn mot å stikke noe inn. Det må være barnesikring, høy montering eller utilgjengelig plassering."},
  "n823-19": {"Fra stikkontaktkursen i stua, sammen med annet utstyr, og med automatisk utkobling ved feil":"Utstyr som ikke må stoppe skal ha egen kurs, ikke deles med stikkontakter i stua. Automatisk utkobling ved feil er ikke riktig her.","Med 300 mA jordfeilvern felles med lyset og andre kurser i samme tavle, slik at det gir god beskyttelse":"Felles kurs med lyset er feil. Utstyret skal ha egen kurs og en metode som ikke kobler ut ved feil.","Uten noe vern, siden utstyret er merket CE og dermed er trygt å bruke uten egen kurs, utkobling eller vern i det hele tatt":"CE-merking betyr ikke at utstyret er trygt uten vern. Det skal ha egen kurs og annen beskyttelse, for eksempel dobbel isolasjon."},
  "n823-20": {"1,0 m over gulvet":"1,0 m er under den høyeste tillatte høyden, ikke selve grensen. Kravet er et tak, og det er høyere enn dette.","2,5 m over gulvet":"2,5 m er over den høyeste tillatte høyden. Uttakene skal sitte lavere, for å redusere bruk av skjøteledninger.","Det er ingen grense":"Det finnes en øvre grense. Uttakene skal sitte høyst i en bestemt høyde, for å redusere skjøteledninger."},
  "bf8": {"Ingenting spesielt, fordi den er jordet":"Jording er ikke nok for barn. Vanlige stikkontakter skal ha barnesikring, sitte minst 1,5 m over gulvet eller være utilgjengelige.","Den må ha kapslingsgrad IP44 eller høyere":"IP44 handler om vern mot vann og fremmedlegemer, ikke om barn. Her må det være barnesikring, eller høy montering.","Den må ha 300 mA jordfeilvern i stedet for 30 mA":"300 mA er brannvern, og det løser ikke faren for barn. Stikkontakten må ha barnesikring, eller være utilgjengelig for barn."},
  "bf9": {"Den må kobles til 400 V på egen kurs, og den kan monteres 0,5 m over gulvet i garasjen for enkel tilgang":"Egen kurs og 400 V endrer ikke høyden. På 0,5 m må kontakten være forriglet eller utilgjengelig for barn.","Den må ha 300 mA jordfeilvern i stedet for 30 mA, uansett hvordan den er montert i garasjen":"300 mA gir ikke barnesikring. Kravet ved lav montering er forrigling, eller at kontakten er utilgjengelig for barn.","Ingenting, CEE-kontakter er tillatt i bolig uten forrigling eller spesielle tiltak for barn i garasjen eller boden":"CEE-kontakter i bolig krever tiltak. På 0,5 m når barn kontakten, så den må være forriglet eller utilgjengelig for barn."},
  "j1": {"Ja, hvis rørene er av kobber og ligger i jord under frostfri dybde, og de ikke brukes til gass":"Materiale og dybde endrer ikke saken. Rørene skal utjevnes til hovedjordskinnen, men de kan ikke være jordelektroden.","Ja, i TN-system, der rørene kan tjene som jordelektrode for hele anlegget og slippe andre jordinger":"TN-system gjør ikke rørene til jordelektrode. De skal utjevnes, men de kan ikke brukes som jordelektrode for anlegget.","Bare hvis rørene ligger i frostfri dybde og er merket som vannledning":"Merking og dybde gjør ikke vannrør til jordelektrode. Rørene skal utjevnes, men de er ikke elektroden."},
  "j2": {"Det er forbudt som jordspyd, men kan brukes som line forlagt i jord":"Her er det snudd på. Som line i jord frarådes det, mens det som jordspyd er tillatt.","Det er det anbefalte materialet for fundamentjording og som line forlagt i jord":"Som line i jord er kobberkledd stål frarådt, så det kan ikke være det anbefalte valget.","Det kan brukes i IT-system og TN-system, men må ligge over bakken og ikke i jord":"En jordelektrode skal ligge i jord for å virke. Over bakken blir den ikke en jordelektrode, uansett system."},
  "j3": {"Kobbertråd i en plastslange under bakken, siden plasten isolerer den mot jorden":"Plastslangen isolerer tråden fra jorda. En jordelektrode må ha god kontakt med jorden for å virke.","Gassrøret i huset, som er godkjent som jordelektrode når det er i kontakt med grunnvann i jorda rundt bygget":"Gassrør er ikke godkjent som jordelektrode. Rørsystemer for brennbare gasser skal aldri brukes.","En kobberleder lagt direkte i en innsjø eller i en dam, der den gir god kontakt med vannet":"Jordelektroder skal ikke legges direkte i dam, elv eller innsjø, så dette er ikke et godt valg."},
  "j4": {"Med vridd jernwire og en fast tape rundt skjøten, som sikrer god kontakt over tid":"Vridd jernwire er ikke egnet for beskyttelsesformål. Skjøter skal være varige og beskyttet mot korrosjon.","Med isolasjonstape rundt skjøten, og skjøten beskyttes mot korrosjon med vanlig tape":"Tape er ikke en varig forbindelse. Skjøter skal være varige og beskyttet mot korrosjon, ikke bare tapet.","De trenger ikke kobles sammen hvis de ligger nær hverandre og er i samme jord":"Nærhet er ikke en forbindelse. Delene må kobles sammen på en varig og god måte."},
  "j5": {"Det holder med jordelektroden i TN-system, siden den ikke trengs i IT- eller TT-anlegg":"Dette er feil. I IT- og TT-anlegg er jordelektroden det som gir jordforbindelsen, så den trengs.","At den er et jordspyd på minst 6 m, valgt uten hensyn til grunnforholdene og jordtypen":"Lengde alene er ikke kravet. Jordelektroden må velges ut fra grunnforholdene og den motstanden som kreves.","At den kobles til nettselskapets PEN-leder, slik at jordelektroden ikke trenger egen måling":"Å koble til nettselskapets PEN-leder erstatter ikke jordelektroden. I IT- og TT-anlegg må jordelektroden virke selv."},
  "j6": {"Kun 6 mm² Cu eller 35 mm² Al":"6 mm² kobber er under minstekravet for PEN-leder. Kravet er høyere, og lederen skal tåle både driftsstrøm og feilstrøm.","2,5 mm² Cu eller 4 mm² Al":"2,5 mm² og 4 mm² er for små. PEN-lederen fører driftsstrøm som nøytralleder og må tåle feilstrøm som beskyttelsesleder.","4 mm² Cu eller 6 mm² Al":"Tallene er for små for både kobber og aluminium. PEN-lederen må ha større tverrsnitt for å være trygg i fast anlegg."},
  "j7": {"Den kan kobles til jord igjen i underfordelingene, så lenge det bare er én N-leder som går ut fra PEN-lederen i fordelingen":"N-lederen skal ikke kobles til jord igjen i underfordelingene. Da kan driftsstrøm gå i beskyttelseslederen.","Den skal ha samme farge som PE, altså grønn/gul, og den skal kobles til samme klemme som PE":"N-lederen skal ikke ha grønn/gul farge, og den skal ikke kobles til samme klemme som PE. Blå er fargen for N.","Den kan brukes som PE for lysarmaturer og stikkontakter i hele anlegget, uten krav til egen klemme":"N-lederen kan ikke erstatte PE, selv om den går til lysarmaturer og stikkontakter. Kobles N og PE sammen igjen, går driftsstrøm i PE."},
  "j8": {"Ja, hvis den er allpolig og merket for 400 V, slik at det kan brytes helt samtidig":"Allpolig bryter er likevel ikke lov i PEN-lederen. Brytes PEN, mister utsatte deler forbindelsen til jord.","Ja, i TN-C-S-anlegg der PEN-lederen er delt i N og PE etter inntaket i huset":"Delingen i TN-C-S endrer ikke saken. PEN-lederen skal ikke brytes, og da kan utsatte deler få farlig spenning.","Ja, en sikring kan settes i PEN-lederen, siden den ikke bryter PEN ved vanlig overlast":"En sikring kan utløse og bryte PEN-lederen. Da mister utsatte deler jordforbindelsen og kan få farlig spenning."},
  "j9": {"Den skal frakobles før faselederne i tavla":"Nøytralen skal ikke kobles fra før fasene. Den skal frakobles i samme øyeblikk som fasene.","Den skal frakobles etter faselederne i tavla":"Etter fasene er også feil. Nøytralen skal kobles fra samtidig med fasene, slik at hver kurs blir fullt frakoblet.","Den skal stå tilkoblet, bare faselederne frakobles":"Å la nøytralen stå på er feil. Frakoblingen skal skje samtidig, og utstyret bør helst være allpolig."},
  "j10": {"Ingenting spesielt, så lenge kapslingen er tett og har IP-grad IP44":"Tett kapsling og IP-grad gir ikke varsel. Den som åpner må få vite at flere tilførsler må kobles fra.","At kapslingen er rød og merket med en gul trekant på forsiden av tavla":"Farge og trekant er ikke kravet. Det som trengs er varsel til den som åpner kapslingen.","At den ene tilførselen har jordfeilvern, og de andre har vanlig vern":"Jordfeilvern på én tilførsel hjelper ikke her. Den som åpner må vite at alle tilførsler må kobles fra."},
  "j11": {"Ja, hvis det er merket for full laststrøm i kursen":"Merking for full last gjør ikke halvledere til frakobling. Halvledere gir ikke et sikkert brudd i kursen.","Ja, når det styres fra en bryter som kan låses":"En låsbar bryter endrer ikke saken. Halvledere gir ikke et sikkert brudd, selv om de styres fra en bryter.","Ja, i boliger, men ikke i næringsbygg":"Stedet spiller ingen rolle. Halvledere gir ikke et sikkert brudd, verken i bolig eller i næringsbygg."},
  "j12": {"Når utstyret er over 10 kW og står i et fast bygg i landbruk":"Effekt og bygning er ikke grunnen. Utkobling kreves når noen kan bli skadet under vedlikehold av utstyret.","Når det er vifter og pumper i landbruk, der utstyret står i stallen":"Vifter og pumper i landbruk er ikke grunnen i seg selv. Det avgjørende er om noen kan bli skadet under vedlikehold.","Det holder med kurssikringen og en vanlig hovedbryter på veggen":"Kurssikring og vanlig hovedbryter er ikke nok. Utstyret må kobles ut, og det må sikres mot å starte av seg selv."},
  "j13": {"Med en grønn lampe som viser at kursen er strømførende, uten symboler":"En grønn lampe er ikke markering av utkoblet stilling. Bryteren må vise stillingen med symboler eller synlige kontakter.","Det er ikke krav til markering, men bryteren skal være plassert høyt på veggen":"Det er krav til markering. Bryteren skal være lett å identifisere og betjene, og merket slik at det er tydelig.","Med symbolene «I» (utkoblet) og «O» (innkoblet), uten annen markering":"Symbolene er byttet om. O betyr utkoblet og I betyr innkoblet, og det må stemme."},
  "j14": {"Grønn på hvit bakgrunn":"Grønn og hvit er ikke fargene her. Betjeningen skal være lett å kjenne igjen, og tekst alene er ikke nok.","Gul på svart bakgrunn":"Gul på svart er ikke kravet. Betjeningen skal være tydelig og lett å kjenne igjen når noe haster.","Blå":"Blå er ikke fargen for nødutkobling. Den skal være lett å kjenne igjen, og tekst skal ikke være eneste merking."},
  "j15": {"Ja, det er den raskeste metoden":"Raskt er ikke avgjørende. Nødutkobling skal kunne bryte full laststrøm, og det kan ikke en plugg og stikkontakt gjøre.","Ja, hvis stikkontakten er en CEE-kontakt":"CEE-kontakt endrer ikke saken. Plugg og stikkontakt er ikke beregnet til å bryte full laststrøm ved nødutkobling.","Ja, under 16 A":"Strømstørrelsen spiller ingen rolle her. Nødutkobling skal kunne bryte full laststrøm, også fra fastlåste motorer."},
  "j16": {"Anlegget skal starte automatisk, uten at noen trykker på startknappen igjen":"Automatisk start er ikke riktig her. Gjeninnkobling skal være en egen, bevisst handling.","Det skal komme en alarm og så start etter 10 sekunder":"Forsinket start etter alarm er feil. Gjeninnkobling skal være en egen, bevisst handling fra noen.","Vernene skal løse ut, og anlegget skal kontrolleres av en elektriker":"Å løse ut vern er ikke det som skjer her. Anlegget skal ikke starte igjen av seg selv, og nødutkoblingen har prioritet."},
  "j17": {"Bare beskyttelseslederen, siden den kobler ut ved jordfeil i kursen":"Beskyttelseslederen alene stopper ikke strømmen. Alle faseledere må brytes ved nødutkobling.","Bare nøytrallederen, siden den bærer strømmen tilbake til forsyningen i hele anlegget":"Nøytralen alene er ikke nok. Alle faseledere må brytes, og ved fare for støt alle spenningsførende ledere.","Bare én fase, og nøytral og PE skal følge med i hele anlegget":"Én fase er for lite. Alle faseledere må brytes, og ved fare for støt må alle spenningsførende ledere brytes."},
  "j18": {"Klasse F etter NS EN 13501-6":"Klasse F er ikke nok. Kabler i fast anlegg må være på riktig nivå, og lavere klasser brukes bare til korte tilkoblinger.","Ingen krav, kabler velges fritt":"Det finnes krav. Kabler i fast anlegg skal ikke bidra til å spre brann, så valget er ikke fritt.","Klasse E etter NS EN 13501-6":"Klasse E er ikke kabelklassen som kreves. For kabler i fast anlegg gjelder klasser som har «ca» i navnet."},
  "j19": {"Når tverrsnittet er høyst 710 mm², og røret og termineringspunktet i én av branncellene oppfyller IP20":"IP20 er for lav verdi. Røret og termineringspunktet må oppfylle IP33 for at innvendig tetting kan utelates.","Når røret er av metall og har tverrsnitt inntil 1000 mm², og termineringspunktet har IP20":"Metall og 1000 mm² er ikke grunnlaget. Tverrsnittet må være innenfor grensen, og IP-kravet må være oppfylt.","Når tverrsnittet er over 710 mm², og røret er tettet med IP33 i én av branncellene":"Over 710 mm² er for stort. Da må røret tettes innvendig, også om det er tettet utvendig."},
  "j20": {"La den stå åpen til jobben er ferdig, og tette den til slutt når resten er gjort":"Å la åpningen stå åpen er ikke trygt. Åpninger skal tettes, og ved endringsarbeid settes tetning inn så snart som mulig.","Tette den midlertidig med gips, og først sette inn permanent tetting når bygget er ferdig":"Gips gir ikke alltid samme brannmotstand. Permanent tetting skal settes inn så snart som mulig, ikke først når bygget er ferdig.","Bruke midlertidig tetting, og vente med permanent tetting til byggherren har overtatt":"Å vente til byggherren har overtatt er for sent. Permanent tetting skal settes inn så snart som mulig."},
  "j21": {"Et annet navn for SELV, altså ekstra lav spenning som er trygg uten jording og uten grunnleggende beskyttelse, også ved feil i anlegget":"FELV er ikke SELV. Her er ikke SELV-kravene oppfylt, og lav spenning alene gir ikke trygghet.","Et jordfeilvern for lavspenning der utkoblingen skjer på under 30 mA, og som kan brukes i alle rom":"FELV er ikke et jordfeilvern. Det er en spenning der SELV- eller PELV-kravene ikke er oppfylt.","Spenning over 1000 V, altså høyspenning, som brukes i boliger til belysning og vanlige stikkontakter":"Over 1000 V er ikke FELV. FELV er lav spenning, og den brukes ikke til høyspenning i boliger."},
  "j22": {"Ingenting, de skal være ujordet som i SELV og holdes adskilt fra jord":"FELV er ikke SELV. Utsatte deler skal kobles til beskyttelseslederen i primærkretsen, ikke stå ujordet.","Nøytrallederen i sekundærkretsen, med automatisk utkobling på hver kurs":"Nøytralen i sekundærkretsen er ikke riktig. Automatisk utkobling endrer ikke hvilken leder det gjelder.","En egen jordelektrode i hver stikkontakt, og den skal ikke være tilkoblet tavla i huset":"En egen jordelektrode i hver stikkontakt er ikke løsningen. Beskyttelseslederen i primærkretsen skal brukes."},
  "j23": {"Sjekke at termostaten virker, og at kabelen er varm etter at den er koblet på":"Det er ikke nok at den blir varm. Skader må påvises med målinger før belegget legges.","Utendørs snøsmelting er ikke omfattet av NEK 400, og det holder å måle etter at den er dekket til":"Dette er feil. NEK 400-7-753 gjelder også utendørs tining og frostsikring, og målinger skal gjøres før belegget legges.","Koble den til en vanlig stikkontakt for å teste den, og se om den blir varm":"En test i stikkontakt sier lite om skader. Målinger før legging er det som avslører skader i kabelen."},
  "j24": {"At kabelen er beregnet for jord og har tykk kappe, så den kan legges direkte i jord uten rør, merking eller annen mekanisk beskyttelse, også der det er grunt":"Tykk kappe er ikke nok. Kabler i jord må beskyttes mot skade, eller ligge dypt nok, og de må merkes.","At de ligger minst 2 m dypt, uavhengig av mekanisk beskyttelse, og at merking med kabelplater er valgfritt":"Dybde alene er ikke nok, og merking er ikke valgfritt. Her ligger kablene grunt, så en spade kan treffe dem.","At de er hvite eller grå, slik at de skiller seg ut fra jorda, og at de ligger over 30 cm i dybde uten noen form for merking":"Farge hjelper ikke med å beskytte kabelen. Uten merking og beskyttelse er grunn nedgraving ikke trygt."},
  "j25": {"For å vise datoen den ble montert, slik at den kan kontrolleres hvert femte år":"Dato for montering er ikke grunnen til merkingen. Merkingen skal gjøre det raskt å finne riktig vern ved feil.","For å vise hvor mange watt den tåler og hvilken produsent den er fra":"Watt og produsent er ikke formålet her. Merkingen skal hjelpe ved feilsøking og vedlikehold.","For å vise hvilken fase og hvilket jordfeilvern den er koblet til":"Fase og jordfeilvern er ikke det merkingen er til for. Ved visuell kontroll skal den stemme med dokumentasjonen."},
  "j26": {"Når det er minst 5 cm luft mellom kablene, uten krav til isolasjon eller skillevegg":"Luft mellom kablene gir ikke sikkerhet alene. Kravet handler om isolasjon, skillevegg eller egne rør for å hindre farlig spenning.","Når kablene er merket med ulik farge, og kabelbroen er jordet":"Farge og jording av kabelbroen løser ikke problemet. En feil i kraftkabelen kan gi farlig spenning i ekomkretsen.","Når ekomkablene er skjermet, og skjermen er koblet til PE i begge ender":"Skjerming alene er ikke nok. Det må være isolasjon, skillevegg eller egne rør, så feil ikke gir farlig spenning."},
  "j27": {"At skapet bare har én fase, og forsynes fra et enfaset 230 V TN-C-system":"TN-C er ikke TN-S. I TN-S er PE og N adskilt hele veien, og PEN-leder finnes ikke der.","At det er et IT-system uten nøytral og uten beskyttelsesleder, med isolert nett":"Dette er ikke et IT-nett. TN-S betyr at PE og N finnes som egne ledere, ikke at de mangler.","At skapet er godkjent for 400 kV og har jordet nøytralpunkt i høyspenningsnett":"400 kV er høyspenning, og merkingen gjelder lavspenning. TN-S forteller om PE og N, ikke om spenning på 400 kV."},
  "j28": {"Det holder å koble ut normalkraften, fordi kursen da er helt spenningsløs. Advarselsskilt er ikke nødvendig, og det er nok å kontrollere normalkraften før arbeidet starter":"Normalkraften er ikke alt. Kursen kan være spenningsførende fra UPS, og spenningsløshet skal kontrolleres på arbeidsstedet.","Avbruddsfri kraft er SELV og trygg uten frakobling, så kursen kan jobbes på under spenning. Normalkraften kan forbli tilkoblet, og advarselsskilt er ikke nødvendig":"Avbruddsfri kraft er ikke trygg uten frakobling. Kursen må gjøres spenningsløs, og advarselsskilt skal være der.","UPS-kurser trenger ikke frakobles, fordi batteriet kobles fra ved strømbrudd. Det er nok å koble ut normalkraften, og spenningsløshet trenger ikke kontrolleres":"Feil. UPS-kursen kan være spenningsførende, og alle tilførsler må frakobles før arbeidet starter."},
  "j29": {"For å slå av overspenningsvernet om natta når huset står tomt, og for å spare strøm på både fasen og nøytralen hele tiden":"Overspenningsvernet skal ikke slås av for å spare strøm. Det skal være på hele tiden, fordi alle installasjoner skal ha det.","For å gjøre overspenningsvernet raskere og mer følsomt for lynnedslag, slik at det løser ut før den første spenningstoppen når anlegget blir truffet av lyn":"Et eget vern foran gjør ikke overspenningsvernet mer følsomt. Det beskytter overspenningsvernet mot kortslutning.","Det er bare en hovedbryter for hele tavla, og den skal slå av alle kurser når det oppstår en feil i overspenningsvernet":"Dette er ikke en hovedbryter for hele tavla. Det er en egen avgrening, og den skal ikke slå av alle kurser."},
  "j30": {"Faselederen (L1 eller L2)":"Grønn/gul er reservert for PE, ikke fase. Faseledere er brun, svart eller grå.","Nøytrallederen (N)":"Nøytralen har blå farge, og den blå klemmen er for N. Grønn/gul er reservert for beskyttelsesleder.","Den grå lederen (L3)":"Grå er en fase, ikke PE. Grønn/gul klemme er reservert for beskyttelsesleder."},
  "j31": {"Pluggen til venstre med to store pinner under":"Pluggen til venstre har to store DC-pinner under. De er for hurtiglading med likestrøm, ikke for AC-lading.","Begge er Type 2 for AC-lading":"Den til venstre er ikke ren Type 2 for AC-lading, fordi den har store DC-pinner under.","Ingen av dem, AC-lading skal skje fra vanlig stikkontakt":"AC-lading skal ikke skje fra vanlig stikkontakt. Tilkoblingspunktet skal være Type 2, ikke en vanlig stikkontakt."}
};
